import type { GameState, IndustryDef, IndustryState, UpgradeDef, UpgradeKind } from './types';
import industriesData from './data/industries.json';
import upgradesData from './data/upgrades.json';

export const INDUSTRIES: IndustryDef[] = industriesData as IndustryDef[];
export const UPGRADES: UpgradeDef[] = upgradesData as UpgradeDef[];

export const INDUSTRIES_BY_ID: Map<string, IndustryDef> = new Map(INDUSTRIES.map(d => [d.id, d]));
export const UPGRADES_BY_ID: Map<string, UpgradeDef> = new Map(UPGRADES.map(u => [u.id, u]));

// per-industry list of revenue-affecting upgrades (global + targeted). Static.
const REVENUE_UPGRADES_FOR: Map<string, UpgradeDef[]> = (() => {
  const m = new Map<string, UpgradeDef[]>();
  for (const def of INDUSTRIES) m.set(def.id, []);
  for (const up of UPGRADES) {
    const kind = up.kind ?? 'revenue';
    if (kind !== 'revenue') continue;
    if (up.industryId === 'global') {
      for (const def of INDUSTRIES) m.get(def.id)!.push(up);
    } else {
      const arr = m.get(up.industryId);
      if (arr) arr.push(up);
    }
  }
  return m;
})();

// resolved customer upgrade effects, recomputed per access
export interface CustomerEffects {
  spawnRate: number;          // multiplier
  walkSpeed: number;          // multiplier
  shopDwell: number;          // multiplier (lower = faster)
  wealthyBonus: number;       // additive prob (0..1)
  whaleBonus: number;         // additive prob (0..1)
  tipMult: number;            // multiplier on all tips
  whaleTip: number;           // extra multiplier on whale tips
  repGainMult: number;        // multiplier
  repLossMult: number;        // multiplier (lower = nicer)
  partialForgive: boolean;
  repRegen: number;           // points / sec
  repDrain: number;           // points / sec lost (shady upgrades)
}

function effectsAccumulator(): CustomerEffects {
  return {
    spawnRate: 1, walkSpeed: 1, shopDwell: 1,
    wealthyBonus: 0, whaleBonus: 0,
    tipMult: 1, whaleTip: 1,
    repGainMult: 1, repLossMult: 1,
    partialForgive: false, repRegen: 0, repDrain: 0
  };
}

let _cachedEffects: CustomerEffects | null = null;
let _cachedEffectsState: GameState | null = null;

// invalidate cached upgrade/synergy data. call after upgrades.* or industry count/unlock mutations.
export function invalidateUpgradeCache(): void {
  _cachedEffects = null;
  _cachedEffectsState = null;
  _cachedRevenueMult.clear();
  _cachedSynergy.clear();
}

export function customerEffects(state: GameState): CustomerEffects {
  if (_cachedEffects && _cachedEffectsState === state) return _cachedEffects;
  const e = computeCustomerEffects(state);
  _cachedEffects = e;
  _cachedEffectsState = state;
  return e;
}

function computeCustomerEffects(state: GameState): CustomerEffects {
  const e = effectsAccumulator();
  for (const up of UPGRADES) {
    if (!state.upgrades[up.id]) continue;
    if (up.repDrain) e.repDrain += up.repDrain;
    const kind: UpgradeKind | undefined = up.kind;
    const v = up.value ?? 0;
    switch (kind) {
      case 'spawn_rate':     e.spawnRate     *= v || 1; break;
      case 'walk_speed':     e.walkSpeed     *= v || 1; break;
      case 'shop_dwell':     e.shopDwell     *= v || 1; break;
      case 'wealthy_rate':   e.wealthyBonus  += v;      break;
      case 'whale_rate':     e.whaleBonus    += v;      break;
      case 'tip_mult':       e.tipMult       *= v || 1; break;
      case 'whale_tip':      e.whaleTip      *= v || 1; break;
      case 'rep_gain_mult':  e.repGainMult   *= v || 1; break;
      case 'rep_loss_mult':  e.repLossMult   *= v || 1; break;
      case 'partial_forgive': if (v) e.partialForgive = true; break;
      case 'rep_regen':      e.repRegen      += v;      break;
    }
  }
  return e;
}

export function defaultState(): GameState {
  const industries: Record<string, IndustryState> = {};
  for (const def of INDUSTRIES) {
    industries[def.id] = {
      count: 0,
      unlocked: def.unlockCost === 0,
      hasManager: false,
      employees: 0,
      hiringUntil: null,
      progress: 0,
      producing: false,
      closed: false,
      paused: false,
      managerProductsServed: 0,
      employeeProductsServed: 0
    };
  }
  // start with one of first industry so player can earn immediately
  const first = INDUSTRIES[0];
  if (first) industries[first.id]!.count = 1;
  return {
    money: 0,
    totalEarned: 0,
    totalProduced: 0,
    industries,
    upgrades: {},
    delivered: {},
    reputation: 500,
    shopStats: {},
    lastTick: Date.now(),
    startedAt: Date.now()
  };
}

export function emptyShopStats(): import('./types').ShopStats {
  return { extraEarned: 0, extraLost: 0, repGained: 0, repLost: 0, sales: 0, misses: 0, unitsSold: 0, feesPaid: 0 };
}

// sales milestones: stack on top of unit milestones.
// each tier multiplies that store's revenue + tips.
export const SALES_MILESTONES: { units: number; mult: number; label: string }[] = [
  { units: 50,      mult: 1.25, label: 'Regulars' },
  { units: 250,     mult: 1.50, label: 'Word-of-mouth' },
  { units: 1000,    mult: 2.00, label: 'Local favorite' },
  { units: 5000,    mult: 3.00, label: 'Neighborhood icon' },
  { units: 25000,   mult: 5.00, label: 'City landmark' },
  { units: 100000,  mult: 8.00, label: 'Regional chain' },
  { units: 500000,  mult: 15.0, label: 'National brand' },
  { units: 2000000, mult: 25.0, label: 'Global empire' }
];

export function salesMilestoneMultiplier(unitsSold: number): number {
  let m = 1;
  for (const s of SALES_MILESTONES) {
    if (unitsSold >= s.units) m = s.mult; else break;
  }
  return m;
}

export function nextSalesMilestone(unitsSold: number): { next: number | null; mult: number; label: string } | null {
  for (const s of SALES_MILESTONES) {
    if (unitsSold < s.units) return { next: s.units, mult: s.mult, label: s.label };
  }
  return null;
}

export function currentSalesMilestone(unitsSold: number): { units: number; mult: number; label: string } | null {
  let cur: { units: number; mult: number; label: string } | null = null;
  for (const s of SALES_MILESTONES) {
    if (unitsSold >= s.units) cur = s; else break;
  }
  return cur;
}

export const REPUTATION_MIN = 1;
export const REPUTATION_MAX = 1000;
export const REPUTATION_GAIN = 2;
export const REPUTATION_LOSS = 5;
// tip is bonus on top of cycle revenue — keep small so customers don't dwarf production
export const TIP_FRACTION = 0.2;

// per-sale fees deducted from gross tip before it hits the wallet.
// DELIVERY: per-unit logistics cost, scales with industry baseRevenue (richer shops have pricier logistics).
// TRANSACTION: credit-card-style cut on gross tip (~2.9%).
// PLATFORM: flat per-sale handling fee, anchored to baseRevenue so low-tier shops pay pennies.
export const FEE_DELIVERY_PER_UNIT_RATE = 0.06;   // 6% of baseRevenue per unit
export const FEE_TRANSACTION_RATE = 0.029;        // 2.9% of gross tip
export const FEE_PLATFORM_PER_SALE_RATE = 0.04;   // 4% of baseRevenue flat per sale

export interface SaleFees {
  delivery: number;
  transaction: number;
  platform: number;
  total: number;
}

export function computeSaleFees(
  def: IndustryDef,
  grossTip: number,
  unitsSold: number
): SaleFees {
  const delivery = def.baseRevenue * FEE_DELIVERY_PER_UNIT_RATE * unitsSold;
  const transaction = grossTip * FEE_TRANSACTION_RATE;
  const platform = def.baseRevenue * FEE_PLATFORM_PER_SALE_RATE;
  const total = delivery + transaction + platform;
  return { delivery, transaction, platform, total };
}

export function clampReputation(v: number): number {
  return Math.max(REPUTATION_MIN, Math.min(REPUTATION_MAX, v));
}

// rep 1 → 0.5x, rep 500 → ~1.0x, rep 1000 → 1.5x
export function reputationMultiplier(rep: number): number {
  return 0.5 + (clampReputation(rep) - 1) / 999;
}

// penalty multiplier is inverse: low rep punishes harder
// rep 1 → 1.5x, rep 500 → 1.0x, rep 1000 → 0.5x
export function reputationPenaltyMultiplier(rep: number): number {
  return 2 - reputationMultiplier(rep);
}

export function reputationSpawnMultiplier(rep: number): number {
  return reputationMultiplier(rep);
}

const _cachedRevenueMult: Map<string, number> = new Map();

function upgradeMult(def: IndustryDef, state: GameState): number {
  const cached = _cachedRevenueMult.get(def.id);
  if (cached !== undefined) return cached;
  let mult = 1;
  const list = REVENUE_UPGRADES_FOR.get(def.id);
  if (list) {
    for (const up of list) {
      if (state.upgrades[up.id]) mult *= up.multiplier ?? 1;
    }
  }
  _cachedRevenueMult.set(def.id, mult);
  return mult;
}

// classic idle milestones — every threshold doubles per-unit output.
// keeps low-tier industries scaling into late game.
export const MILESTONE_THRESHOLDS = [
  25, 50, 100, 200, 300, 400, 500, 750, 1000,
  1500, 2000, 3000, 4000, 5000, 7500, 10000
];

export function unitMilestoneMultiplier(count: number): number {
  let m = 1;
  for (const t of MILESTONE_THRESHOLDS) {
    if (count >= t) m *= 2; else break;
  }
  return m;
}

export function nextMilestone(count: number): { next: number | null; mult: number } {
  for (const t of MILESTONE_THRESHOLDS) {
    if (count < t) return { next: t, mult: unitMilestoneMultiplier(t) };
  }
  return { next: null, mult: unitMilestoneMultiplier(count) };
}

// each OTHER industry that's unlocked grants a small synergy boost.
// rewards diversification — buying late-tier helps early-tier revenue too.
// additive scaling: avoids runaway compounding when many industries exist.
export const SYNERGY_PER_UNLOCK = 0.02;          // +2% per other unlocked industry
export const SYNERGY_BIG_BONUS = 0.05;           // +5% per other industry with 100+ units

const _cachedSynergy: Map<string, number> = new Map();

export function synergyMultiplier(def: IndustryDef, state: GameState): number {
  const cached = _cachedSynergy.get(def.id);
  if (cached !== undefined) return cached;
  let bonus = 0;
  for (const other of INDUSTRIES) {
    if (other.id === def.id) continue;
    const ind = state.industries[other.id];
    if (!ind || !ind.unlocked) continue;
    bonus += SYNERGY_PER_UNLOCK;
    if (ind.count >= 100) bonus += SYNERGY_BIG_BONUS;
  }
  const v = 1 + bonus;
  _cachedSynergy.set(def.id, v);
  return v;
}

function salesMultFor(state: GameState, defId: string): number {
  const s = state.shopStats[defId];
  return salesMilestoneMultiplier(s?.unitsSold ?? 0);
}

// includes reputation buff/nerf — used for cycle revenue + customer tip
export function perUnitRevenue(def: IndustryDef, state: GameState): number {
  const ind = state.industries[def.id];
  const milestone = ind ? unitMilestoneMultiplier(ind.count) : 1;
  const empBonus = ind ? employeeRevenueMultiplier(ind.employees) : 1;
  return def.baseRevenue
    * upgradeMult(def, state)
    * milestone
    * salesMultFor(state, def.id)
    * synergyMultiplier(def, state)
    * empBonus
    * reputationMultiplier(state.reputation);
}

// no reputation buff — used as base for empty-store penalty
export function perUnitBase(def: IndustryDef, state: GameState): number {
  const ind = state.industries[def.id];
  const milestone = ind ? unitMilestoneMultiplier(ind.count) : 1;
  const empBonus = ind ? employeeRevenueMultiplier(ind.employees) : 1;
  return def.baseRevenue
    * upgradeMult(def, state)
    * milestone
    * salesMultFor(state, def.id)
    * synergyMultiplier(def, state)
    * empBonus;
}

export function migrateState(loaded: GameState): GameState {
  const fresh = defaultState();
  // merge industries (new content added in updates)
  for (const def of INDUSTRIES) {
    if (!loaded.industries[def.id]) {
      loaded.industries[def.id] = fresh.industries[def.id]!;
    }
  }
  if (!loaded.upgrades) loaded.upgrades = {};
  if (!loaded.delivered) loaded.delivered = {};
  if (typeof loaded.totalEarned !== 'number') loaded.totalEarned = loaded.money;
  if (typeof loaded.totalProduced !== 'number') loaded.totalProduced = 0;
  if (typeof loaded.startedAt !== 'number') loaded.startedAt = Date.now();
  if (typeof loaded.reputation !== 'number') loaded.reputation = 500;
  loaded.reputation = clampReputation(loaded.reputation);
  if (!loaded.shopStats) loaded.shopStats = {};
  for (const k of Object.keys(loaded.shopStats)) {
    const s = loaded.shopStats[k]!;
    if (typeof s.unitsSold !== 'number') s.unitsSold = 0;
    if (typeof s.feesPaid !== 'number') s.feesPaid = 0;
  }
  for (const def of INDUSTRIES) {
    const ind = loaded.industries[def.id]!;
    if (typeof ind.employees !== 'number') ind.employees = 0;
    if (ind.hiringUntil === undefined) ind.hiringUntil = null;
    if (typeof ind.closed !== 'boolean') ind.closed = false;
    if (typeof ind.paused !== 'boolean') ind.paused = false;
    if (typeof ind.managerProductsServed !== 'number') ind.managerProductsServed = 0;
    if (typeof ind.employeeProductsServed !== 'number') ind.employeeProductsServed = 0;
  }
  return loaded;
}

// salary rates (per second) and severance factor.
// rates balanced so a productive industry stays net positive,
// but idle/empty staff drains money — incentive to fire dead weight.
export const MANAGER_SALARY_RATE = 0.008;        // fraction of managerCost / sec
export const EMPLOYEE_SALARY_RATE = 0.0015;      // fraction of managerCost / sec / employee
// severance = max(products × baseRevenue × factor, salary × min seconds floor)
// factor tuned so long-serving staff get meaningful payout
export const SEVERANCE_FACTOR = 4.0;
export const MIN_SEVERANCE_SECONDS = 240;        // floor: 4 minutes of pay even for fresh hires

export function managerSalaryPerSec(def: IndustryDef): number {
  return def.managerCost * MANAGER_SALARY_RATE;
}

export function employeeSalaryPerSec(def: IndustryDef, employees: number): number {
  return def.managerCost * EMPLOYEE_SALARY_RATE * employees;
}

export function managerSeverance(def: IndustryDef, state: GameState): number {
  const ind = state.industries[def.id];
  if (!ind) return 0;
  const earned = ind.managerProductsServed * def.baseRevenue * SEVERANCE_FACTOR;
  const floor = managerSalaryPerSec(def) * MIN_SEVERANCE_SECONDS;
  return Math.max(earned, floor);
}

// severance for firing a single employee = share of pooled service products
export function employeeSeverance(def: IndustryDef, state: GameState): number {
  const ind = state.industries[def.id];
  if (!ind || ind.employees <= 0) return 0;
  const share = ind.employeeProductsServed / ind.employees;
  const earned = share * def.baseRevenue * SEVERANCE_FACTOR;
  const floor = employeeSalaryPerSec(def, 1) * MIN_SEVERANCE_SECONDS;
  return Math.max(earned, floor);
}

export function fireManager(state: GameState, defId: string): number {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return 0;
  const ind = state.industries[def.id];
  if (!ind || !ind.hasManager) return 0;
  const sev = managerSeverance(def, state);
  state.money = Math.max(0, state.money - sev);
  ind.hasManager = false;
  ind.managerProductsServed = 0;
  return sev;
}

export function fireEmployee(state: GameState, defId: string): number {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return 0;
  const ind = state.industries[def.id];
  if (!ind || ind.employees <= 0) return 0;
  const sev = employeeSeverance(def, state);
  state.money = Math.max(0, state.money - sev);
  // remove one employee's share of the pooled service products (floored to keep counter integer)
  const share = Math.floor(ind.employeeProductsServed / ind.employees);
  ind.employeeProductsServed = Math.max(0, ind.employeeProductsServed - share);
  ind.employees -= 1;
  if (ind.employees === 0) ind.employeeProductsServed = 0;
  return sev;
}

// fire manager + every employee in one shot. returns total severance paid.
export function fireAll(state: GameState, defId: string): number {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return 0;
  const ind = state.industries[def.id];
  if (!ind) return 0;
  let total = 0;
  if (ind.hasManager) total += managerSeverance(def, state);
  if (ind.employees > 0) {
    // each employee's slice computed against original pool, then pool drained whole
    const share = ind.employeeProductsServed / ind.employees;
    const earned = share * def.baseRevenue * SEVERANCE_FACTOR;
    const floor = employeeSalaryPerSec(def, 1) * MIN_SEVERANCE_SECONDS;
    total += Math.max(earned, floor) * ind.employees;
  }
  state.money = Math.max(0, state.money - total);
  if (ind.hasManager) {
    ind.hasManager = false;
    ind.managerProductsServed = 0;
  }
  ind.employees = 0;
  ind.employeeProductsServed = 0;
  ind.hiringUntil = null;
  return total;
}

export function toggleStoreClosed(state: GameState, defId: string): boolean {
  const ind = state.industries[defId];
  if (!ind || !ind.unlocked) return false;
  ind.closed = !ind.closed;
  return ind.closed;
}

export function toggleProductionPaused(state: GameState, defId: string): boolean {
  const ind = state.industries[defId];
  if (!ind || !ind.unlocked) return false;
  ind.paused = !ind.paused;
  if (ind.paused) {
    // freeze current cycle progress; manager auto-resume blocked by paused check in tick
    ind.producing = false;
  }
  return ind.paused;
}

export function costForNext(def: IndustryDef, count: number, qty: number = 1): number {
  // cost of next `qty` units of an industry currently at `count`
  if (def.costMultiplier === 1) return def.baseCost * qty;
  const r = def.costMultiplier;
  const base = def.baseCost * Math.pow(r, count);
  return base * (Math.pow(r, qty) - 1) / (r - 1);
}

export function maxAffordable(def: IndustryDef, count: number, money: number): number {
  // largest qty such that costForNext(def, count, qty) <= money
  if (money < costForNext(def, count, 1)) return 0;
  const r = def.costMultiplier;
  const base = def.baseCost * Math.pow(r, count);
  if (r === 1) return Math.floor(money / def.baseCost);
  // money >= base * (r^q - 1) / (r - 1)
  // r^q <= money*(r-1)/base + 1
  const lhs = money * (r - 1) / base + 1;
  return Math.floor(Math.log(lhs) / Math.log(r));
}

export function industryRevenue(def: IndustryDef, state: GameState): number {
  const ind = state.industries[def.id]!;
  const milestone = unitMilestoneMultiplier(ind.count);
  return def.baseRevenue * ind.count
    * upgradeMult(def, state)
    * milestone
    * salesMultFor(state, def.id)
    * synergyMultiplier(def, state)
    * employeeRevenueMultiplier(ind.employees)
    * reputationMultiplier(state.reputation);
}

// each employee shaves 8% off cycle time, multiplicative, floor 15% of base
export const EMPLOYEE_SPEED_FACTOR = 0.92;
export const EMPLOYEE_MIN_CYCLE = 0.15;
export const EMPLOYEE_MAX = 25;   // global fallback when industry has no override

export function employeeMaxFor(def: IndustryDef): number {
  return def.employeeMax ?? EMPLOYEE_MAX;
}

export function employeeSpeedMultiplier(employees: number): number {
  return Math.max(EMPLOYEE_MIN_CYCLE, Math.pow(EMPLOYEE_SPEED_FACTOR, employees));
}

// once the speed floor is hit, extra employees stop shaving cycle time and
// instead boost per-cycle revenue (overtime/throughput crew). +5% per extra.
export const EMPLOYEE_SPEED_FLOOR_AT = Math.ceil(
  Math.log(EMPLOYEE_MIN_CYCLE) / Math.log(EMPLOYEE_SPEED_FACTOR)
);
export const EMPLOYEE_REVENUE_BONUS = 0.05;

export function employeeRevenueMultiplier(employees: number): number {
  const extra = Math.max(0, employees - EMPLOYEE_SPEED_FLOOR_AT);
  return 1 + EMPLOYEE_REVENUE_BONUS * extra;
}

export function employeeCost(def: IndustryDef, n: number): number {
  // base ~ 30% of manager cost, grows 45% per hire — late employees are luxury
  return Math.ceil(def.managerCost * 0.3 * Math.pow(1.45, n));
}

// hiring takes time — scales w/ existing employees (recruitment harder as team grows)
export const HIRE_BASE_SECONDS = 5;
export const HIRE_PER_EMPLOYEE = 2;
export const HIRE_MAX_SECONDS = 60;

export function employeeHireDuration(n: number): number {
  return Math.min(HIRE_MAX_SECONDS, HIRE_BASE_SECONDS + n * HIRE_PER_EMPLOYEE);
}

export function hireEmployee(state: GameState, defId: string): boolean {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return false;
  const ind = state.industries[def.id]!;
  if (!ind.unlocked) return false;
  if (ind.employees >= employeeMaxFor(def)) return false;
  if (ind.hiringUntil !== null) return false;  // already hiring
  const cost = employeeCost(def, ind.employees);
  if (state.money < cost) return false;
  state.money -= cost;
  const durMs = employeeHireDuration(ind.employees) * 1000;
  ind.hiringUntil = Date.now() + durMs;
  return true;
}

// complete any hires whose timer has elapsed (call each tick + on load)
export function resolveHires(state: GameState, now: number = Date.now()): string[] {
  const completed: string[] = [];
  for (const def of INDUSTRIES) {
    const ind = state.industries[def.id];
    if (!ind || ind.hiringUntil === null) continue;
    if (now >= ind.hiringUntil) {
      ind.employees += 1;
      ind.hiringUntil = null;
      completed.push(def.id);
    }
  }
  return completed;
}

export function industryCycleTime(def: IndustryDef, state: GameState): number {
  const ind = state.industries[def.id]!;
  return def.baseTime * employeeSpeedMultiplier(ind ? ind.employees : 0);
}

export interface BuyResult {
  bought: number;
  cost: number;
}

export function buyIndustry(
  state: GameState,
  defId: string,
  qty: number | 'max'
): BuyResult {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return { bought: 0, cost: 0 };
  const ind = state.industries[def.id]!;
  if (!ind.unlocked) {
    // unlock = buy first unit at unlockCost
    if (state.money < def.unlockCost) return { bought: 0, cost: 0 };
    state.money -= def.unlockCost;
    ind.unlocked = true;
    ind.count = 1;
    ind.closed = true;
    invalidateUpgradeCache();
    return { bought: 1, cost: def.unlockCost };
  }
  const want = qty === 'max' ? maxAffordable(def, ind.count, state.money) : qty;
  if (want <= 0) return { bought: 0, cost: 0 };
  const cost = costForNext(def, ind.count, want);
  if (state.money < cost) return { bought: 0, cost: 0 };
  const prev = ind.count;
  state.money -= cost;
  ind.count += want;
  // synergy threshold (100 units) may have been crossed; invalidate synergy cache
  if (prev < 100 && ind.count >= 100) invalidateUpgradeCache();
  return { bought: want, cost };
}

export function buyManager(state: GameState, defId: string): boolean {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return false;
  const ind = state.industries[def.id]!;
  if (ind.hasManager) return false;
  if (state.money < def.managerCost) return false;
  state.money -= def.managerCost;
  ind.hasManager = true;
  return true;
}

export function buyUpgrade(state: GameState, upgradeId: string): boolean {
  const up = UPGRADES_BY_ID.get(upgradeId);
  if (!up) return false;
  if (state.upgrades[up.id]) return false;
  if (up.industryId !== 'global' && up.industryId !== 'customer') {
    const ind = state.industries[up.industryId];
    if (!ind) return false;
    if (up.requires && ind.count < up.requires) return false;
  }
  if (state.money < up.cost) return false;
  state.money -= up.cost;
  state.upgrades[up.id] = true;
  invalidateUpgradeCache();
  return true;
}

export function startProduction(state: GameState, defId: string): boolean {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return false;
  const ind = state.industries[def.id]!;
  if (ind.count <= 0) return false;
  if (ind.paused) return false;
  if (ind.producing) return false;
  ind.producing = true;
  ind.progress = 0;
  return true;
}

export interface TickResult {
  earned: number;
  completions: Record<string, number>;
}

export function tick(state: GameState, dt: number): TickResult {
  let earned = 0;
  let salary = 0;
  const completions: Record<string, number> = {};
  const fx = customerEffects(state);
  const repDelta = (fx.repRegen - fx.repDrain) * dt;
  if (repDelta !== 0) {
    state.reputation = clampReputation(state.reputation + repDelta);
  }
  for (const def of INDUSTRIES) {
    const ind = state.industries[def.id]!;
    // salary paid regardless of production
    if (ind.hasManager) salary += managerSalaryPerSec(def) * dt;
    if (ind.employees > 0) salary += employeeSalaryPerSec(def, ind.employees) * dt;

    if (ind.count <= 0) continue;
    if (ind.paused) continue;        // production paused; salary already paid above
    if (!ind.producing && !ind.hasManager) continue;

    const cycle = industryCycleTime(def, state);
    const revPerCycle = industryRevenue(def, state);

    if (!ind.producing && ind.hasManager) {
      ind.producing = true;
      ind.progress = 0;
    }

    let remaining = dt;
    while (remaining > 0 && ind.producing) {
      const needed = (1 - ind.progress) * cycle;
      if (remaining >= needed) {
        remaining -= needed;
        earned += revPerCycle;
        completions[def.id] = (completions[def.id] ?? 0) + 1;
        state.totalProduced += ind.count;
        // track service productivity for severance
        if (ind.hasManager) ind.managerProductsServed += 1;
        if (ind.employees > 0) ind.employeeProductsServed += 1;
        ind.progress = 0;
        if (ind.hasManager) {
          ind.producing = true;
        } else {
          ind.producing = false;
          break;
        }
      } else {
        ind.progress += remaining / cycle;
        remaining = 0;
      }
    }
  }
  state.money += earned;
  state.totalEarned += earned;
  state.money = Math.max(0, state.money - salary);
  return { earned, completions };
}

export function offlineProgress(state: GameState, now: number): number {
  const dt = Math.max(0, (now - state.lastTick) / 1000);
  const capped = Math.min(dt, 8 * 3600);
  resolveHires(state, now);
  const { earned } = tick(state, capped);
  state.lastTick = now;
  return earned;
}
