const SUFFIXES = [
  '', 'K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp', 'Oc', 'No',
  'Dc', 'UDc', 'DDc', 'TDc', 'QaDc', 'QiDc', 'SxDc', 'SpDc', 'OcDc', 'NDc',
  'Vg', 'UVg', 'DVg', 'TVg', 'QaVg', 'QiVg', 'SxVg', 'SpVg', 'OcVg', 'NVg'
];

const POW1000: number[] = SUFFIXES.map((_, i) => Math.pow(1000, i));

export function formatMoney(n: number): string {
  if (!isFinite(n)) return '∞';
  if (n < 0) return '-' + formatMoney(-n);
  if (n < 1000) return '$' + n.toFixed(n < 10 ? 2 : 0);
  const tier = Math.floor(Math.log10(n) / 3);
  const idx = Math.min(tier, SUFFIXES.length - 1);
  const scaled = n / POW1000[idx]!;
  return '$' + scaled.toFixed(scaled < 10 ? 3 : scaled < 100 ? 2 : 1) + SUFFIXES[idx];
}

export function formatTime(seconds: number): string {
  if (seconds < 1) return seconds.toFixed(2) + 's';
  if (seconds < 60) return seconds.toFixed(1) + 's';
  if (seconds < 3600) return Math.floor(seconds / 60) + 'm ' + Math.floor(seconds % 60) + 's';
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  return h + 'h ' + m + 'm';
}

export function formatNumber(n: number): string {
  if (n < 1000) return Math.floor(n).toString();
  return formatMoney(n).substring(1);
}
