export interface LogEntry {
  ts: number;
  msg: string;
  color?: string;
}

export interface NotifyOpts {
  color?: string;
}

type Subscriber = (e: LogEntry) => void;

const subs: Subscriber[] = [];

export function notify(msg: string, opts?: NotifyOpts): void {
  const entry: LogEntry = { ts: Date.now(), msg, color: opts?.color };
  for (const fn of subs) fn(entry);
}

export function onLog(fn: Subscriber): void {
  subs.push(fn);
}
