type BuyQty = 1 | 10 | 100 | 'max';

type UpgradeGroup = 'customer' | 'global' | 'industry';

interface UI {
  state: GameState;
  buyQty: BuyQty;
  tab: 'industries' | 'upgrades';
  industryCategory: string;   // 'All' or a category name
  upgradeGroup: UpgradeGroup;
  notify(msg: string, opts?: NotifyOpts): void;
}

const CATEGORY_ICONS: Record<string, string> = {
  Food: 'burger',
  Lifestyle: 'bag',
  Agriculture: 'wheat',
  Health: 'hospitalCross',
  Entertainment: 'theater',
  'Real Estate': 'house',
  Tech: 'laptop',
  Finance: 'bank',
  Travel: 'plane',
  Energy: 'bolt'
};

function hireAvailability(def: IndustryDef, ind: IndustryState, money: number): { mgr: boolean; emp: boolean } {
  if (!ind.unlocked) return { mgr: false, emp: false };
  const mgr = !ind.hasManager && money >= def.managerCost;
  const empCap = employeeMaxFor(def);
  const hiring = ind.hiringUntil !== null;
  const emp = ind.employees < empCap && !hiring && money >= employeeCost(def, ind.employees);
  return { mgr, emp };
}

function canBuildCard(def: IndustryDef, ind: IndustryState, money: number, buyQty: BuyQty): boolean {
  if (!ind.unlocked) return money >= def.unlockCost;
  if (ind.count === 0) return money >= def.baseCost;
  const q = buyQty === 'max' ? maxAffordable(def, ind.count, money) : buyQty;
  if (q <= 0) return false;
  return money >= costForNext(def, ind.count, Math.max(1, q));
}

function subtabBuildableCount(category: string, state: GameState, buyQty: BuyQty): number {
  let n = 0;
  for (const def of INDUSTRIES) {
    if ((def.category ?? 'Misc') !== category) continue;
    const ind = state.industries[def.id]!;
    if (canBuildCard(def, ind, state.money, buyQty)) n++;
  }
  return n;
}

function industryCategories(): string[] {
  const seen = new Set<string>();
  const order: string[] = [];
  for (const def of INDUSTRIES) {
    const c = def.category ?? 'Misc';
    if (!seen.has(c)) { seen.add(c); order.push(c); }
  }
  return order;
}

export function mountUI(state: GameState, notify: (msg: string, opts?: NotifyOpts) => void): {
  render: () => void;
  tick: () => void;
  ui: UI;
} {
  const firstCat = industryCategories()[0] ?? 'Food';
  const ui: UI = { state, buyQty: 1, tab: 'industries', industryCategory: firstCat, upgradeGroup: 'customer', notify };
  const root = document.getElementById('app')!;
  root.innerHTML = shellHTML();
  attachShellHandlers(ui, root);

  const render = () => renderAll(ui, root);
  const tick = () => updateLive(ui, root);
  render();
  return { render, tick, ui };
}

