function attachShellHandlers(ui: UI, root: HTMLElement): void {
  root.querySelectorAll('.tab').forEach(tab => {
    tab.addEventListener('click', () => {
      const t = (tab as HTMLElement).dataset.tab as UI['tab'];
      ui.tab = t;
      root.querySelectorAll('.tab').forEach(b => b.classList.remove('active'));
      tab.classList.add('active');
      renderAll(ui, root);
    });
  });

  root.querySelector('#btn-reset')!.addEventListener('click', () => {
    if (confirm('Wipe save and start over?')) {
      wipe();
      location.reload();
    }
  });
}

function renderAll(ui: UI, root: HTMLElement): void {
  updateTopbar(ui, root);
  const main = root.querySelector('#main')!;
  const sidebar = root.querySelector('#sidebar')!;
  if (ui.tab === 'industries') main.innerHTML = renderIndustries(ui);
  else main.innerHTML = renderUpgrades(ui);
  sidebar.innerHTML = renderSidebar(ui);
  attachMainHandlers(ui, root);
  attachSidebarHandlers(ui, root);
  updateFooter(ui, root);
}

function renderQtyGroup(ui: UI): string {
  const opts: { v: BuyQty; label: string }[] = [
    { v: 1, label: 'x1' }, { v: 10, label: 'x10' }, { v: 100, label: 'x100' }, { v: 'max', label: 'MAX' }
  ];
  return `<div class="qty-group" id="qty-group">
    ${opts.map(o => `<button data-qty="${o.v}" class="qty ${ui.buyQty === o.v ? 'active' : ''}">${o.label}</button>`).join('')}
  </div>`;
}

function renderSidebar(ui: UI): string {
  if (ui.tab === 'industries') {
    const cats = industryCategories();
    const active = cats.includes(ui.industryCategory) ? ui.industryCategory : (cats[0] ?? '');
    return `
      ${renderQtyGroup(ui)}
      <div class="sidebar-heading">Categories</div>
      <nav class="subtabs">
        ${cats.map(c => {
          const count = INDUSTRIES.filter(d => (d.category ?? 'Misc') === c).length;
          const ownedCount = INDUSTRIES.filter(d => (d.category ?? 'Misc') === c && ui.state.industries[d.id]?.unlocked).length;
          const iconKey = CATEGORY_ICONS[c] ?? 'package';
          const ready = subtabBuildableCount(c, ui.state, ui.buyQty);
          const color = categoryColor(c) ?? '#9aa4b2';
          return `<button class="subtab ${active === c ? 'active' : ''}" data-subtab="${c}" style="--cat-color: ${color}">
            <span class="st-icon">${icon(iconKey, { size: 16 })}</span>
            <span class="st-label">${c}</span>
            <span class="st-ready ${ready > 0 ? 'on' : ''}" data-subtab-ready="${c}" data-last="${ready}" title="Cards you can afford to build/unlock">${icon('coin', { size: 12 })} <span class="st-ready-n">${ready}</span></span>
            <span class="st-count">${ownedCount}/${count}</span>
          </button>`;
        }).join('')}
      </nav>`;
  }
  // upgrades sidebar: group filter
  const groups: { id: UpgradeGroup; label: string; icon: string }[] = [
    { id: 'customer', label: 'Customers', icon: 'people' },
    { id: 'global',   label: 'Global',    icon: 'globe' },
    { id: 'industry', label: 'Industries', icon: 'factory' }
  ];
  return `
    <div class="sidebar-heading">Upgrade Groups</div>
    <nav class="subtabs">
      ${groups.map(g => {
        const color = '#9aa4b2';
        return `<button class="subtab ${ui.upgradeGroup === g.id ? 'active' : ''}" data-upgrade-group="${g.id}" style="--cat-color: ${color}">
          <span class="st-icon">${icon(g.icon, { size: 16 })}</span>
          <span class="st-label">${g.label}</span>
        </button>`;
      }).join('')}
    </nav>`;
}

function attachSidebarHandlers(ui: UI, root: HTMLElement): void {
  const sidebar = root.querySelector('#sidebar')!;
  sidebar.querySelectorAll('#qty-group .qty').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = (btn as HTMLElement).dataset.qty!;
      ui.buyQty = (v === 'max' ? 'max' : Number(v)) as BuyQty;
      renderAll(ui, root);
    });
  });
  sidebar.querySelectorAll('[data-subtab]').forEach(btn => {
    btn.addEventListener('click', () => {
      ui.industryCategory = (btn as HTMLElement).dataset.subtab!;
      renderAll(ui, root);
    });
  });
  sidebar.querySelectorAll('[data-upgrade-group]').forEach(btn => {
    btn.addEventListener('click', () => {
      ui.upgradeGroup = (btn as HTMLElement).dataset.upgradeGroup as UpgradeGroup;
      renderAll(ui, root);
    });
  });
}

function updateTopbar(ui: UI, root: HTMLElement): void {
  const moneyEl = root.querySelector('#money')!;
  const rateEl = root.querySelector('#rate')!;
  moneyEl.textContent = formatMoney(ui.state.money);
  const net = estimatedRate(ui.state);
  const sign = net < 0 ? '-' : '+';
  rateEl.textContent = sign + formatMoney(Math.abs(net)) + '/s';
  (rateEl as HTMLElement).classList.toggle('neg', net < 0);
  (rateEl as HTMLElement).classList.toggle('pos', net > 0);
  const payroll = computePayroll(ui.state);
  const mgrEl = root.querySelector('#sal-mgr') as HTMLElement | null;
  const empEl = root.querySelector('#sal-emp') as HTMLElement | null;
  const totEl = root.querySelector('#sal-total') as HTMLElement | null;
  if (mgrEl) mgrEl.textContent = '-' + formatMoney(payroll.manager) + '/s';
  if (empEl) empEl.textContent = '-' + formatMoney(payroll.employee) + '/s';
  if (totEl) totEl.textContent = '-' + formatMoney(payroll.manager + payroll.employee) + '/s';
  const rep = Math.round(ui.state.reputation);
  const fill = root.querySelector('#rep-fill') as HTMLElement | null;
  const val = root.querySelector('#rep-val') as HTMLElement | null;
  const wrap = root.querySelector('#rep') as HTMLElement | null;
  const buffEl = root.querySelector('#rep-buff') as HTMLElement | null;
  if (fill) fill.style.width = (rep / 10).toFixed(1) + '%';
  if (val) val.textContent = String(rep);
  const mult = reputationMultiplier(ui.state.reputation);
  const pen = reputationPenaltyMultiplier(ui.state.reputation);
  if (buffEl) {
    const sign = mult >= 1 ? '+' : '';
    const pct = Math.round((mult - 1) * 100);
    buffEl.textContent = `${sign}${pct}% rev · ${pen.toFixed(2)}× loss`;
    buffEl.classList.toggle('buff', mult > 1);
    buffEl.classList.toggle('nerf', mult < 1);
  }
  if (wrap) {
    wrap.classList.toggle('rep-low', rep < 300);
    wrap.classList.toggle('rep-high', rep > 700);
  }
}

function updateFooter(ui: UI, root: HTMLElement): void {
  const footer = root.querySelector('#footer')!;
  footer.textContent = `Total earned: ${formatMoney(ui.state.totalEarned)} · ` +
    `Playing: ${formatTime((Date.now() - ui.state.startedAt) / 1000)}`;
}

// per-frame live updates — no innerHTML, no handler rebind.
// safe to call every frame: only mutates text/style of existing nodes,
// so clicks/inputs on cards are never interrupted.
function updateLive(ui: UI, root: HTMLElement): void {
  updateTopbar(ui, root);
  updateFooter(ui, root);
  updateOpenStaffModal(ui);
  if (ui.tab !== 'industries') return;

  // subtab "ready to build" badges — recompute only when money or buyQty changed
  if (ui.state.money !== _lastBadgeMoney || ui.buyQty !== _lastBadgeQty) {
    _lastBadgeMoney = ui.state.money;
    _lastBadgeQty = ui.buyQty;
    root.querySelectorAll('[data-subtab-ready]').forEach(el => {
      const elx = el as HTMLElement;
      const cat = elx.dataset.subtabReady!;
      const n = subtabBuildableCount(cat, ui.state, ui.buyQty);
      if (Number(elx.dataset.last) === n) return;
      elx.dataset.last = String(n);
      const numEl = elx.querySelector('.st-ready-n');
      if (numEl) numEl.textContent = String(n);
      elx.classList.toggle('on', n > 0);
    });
  }

  for (const def of INDUSTRIES) {
    const ind = ui.state.industries[def.id]!;
    const card = root.querySelector(`[data-card="${def.id}"]`) as HTMLElement | null;
    if (!card) continue;
    const fill = card.querySelector('.card-fill') as HTMLElement | null;
    const time = card.querySelector('.status-time') as HTMLElement | null;
    if (!fill) continue;

    const cycle = industryCycleTime(def, ui.state);
    const producing = !ind.paused && (ind.producing || ind.hasManager);
    const pct = Math.max(0, Math.min(100, ind.progress * 100));
    fill.style.width = pct + '%';
    if (time) {
      time.textContent = ind.paused
        ? '⏸ Paused'
        : producing
          ? formatTime((1 - ind.progress) * cycle) + ' left'
          : ind.count > 0 ? '' : 'Buy units first';
    }
    const rateEl = card.querySelector('.sub-rate') as HTMLElement | null;
    if (rateEl && ind.count > 0) {
      const rev = industryRevenue(def, ui.state);
      rateEl.textContent = formatMoney(rev / Math.max(0.0001, cycle)) + '/s';
    }

    // also update buy button affordability without rebinding
    const buyBtn = card.querySelector('button.buy') as HTMLButtonElement | null;
    if (buyBtn && ind.unlocked && ind.count > 0) {
      const qty = ui.buyQty === 'max'
        ? maxAffordable(def, ind.count, ui.state.money)
        : (ui.buyQty as number);
      const cost = costForNext(def, ind.count, Math.max(1, qty));
      const can = qty > 0 && ui.state.money >= cost;
      buyBtn.disabled = !can;
      buyBtn.textContent = `Buy ${qty <= 0 ? 1 : qty} · ${formatMoney(cost)}`;
    } else if (buyBtn && !ind.unlocked) {
      const can = ui.state.money >= def.unlockCost;
      buyBtn.disabled = !can;
    }

    // hire pips on STAFF button
    const pips = card.querySelector(`[data-hire-pips="${def.id}"]`) as HTMLElement | null;
    if (pips) {
      const a = hireAvailability(def, ind, ui.state.money);
      const mgr = pips.querySelector('.pip.mgr') as HTMLElement | null;
      const emp = pips.querySelector('.pip.emp') as HTMLElement | null;
      if (mgr) mgr.classList.toggle('on', a.mgr);
      if (emp) emp.classList.toggle('on', a.emp);
    }
  }
}

// id of industry whose staff modal is currently open (null = closed)
let openStaffDefId: string | null = null;
let openStaffRefresh: (() => void) | null = null;
let openStaffWasHiring = false;

// per-frame change-detection guards for live updates
let _lastBadgeMoney = NaN;
let _lastBadgeQty: BuyQty | null = null;

function updateOpenStaffModal(ui: UI): void {
  if (!openStaffDefId) return;
  const overlay = document.querySelector('.modal-overlay.staff-overlay') as HTMLElement | null;
  if (!overlay) { openStaffDefId = null; openStaffRefresh = null; openStaffWasHiring = false; return; }
  const def = INDUSTRIES_BY_ID.get(openStaffDefId);
  const ind = def ? ui.state.industries[def.id] : null;
  if (!def || !ind) return;
  const hiring = ind.hiringUntil !== null;
  // hire just completed — full rebuild so button reverts to "Hire +1"
  if (openStaffWasHiring && !hiring) {
    openStaffWasHiring = false;
    openStaffRefresh?.();
    return;
  }
  openStaffWasHiring = hiring;
  // live-update only the recruiting timer to avoid stealing focus from buttons
  if (hiring) {
    const dur = employeeHireDuration(ind.employees);
    const remaining = Math.max(0, (ind.hiringUntil! - Date.now()) / 1000);
    const btn = overlay.querySelector('[data-employee]') as HTMLButtonElement | null;
    if (btn) btn.textContent = `⏳ Hiring · ${formatTime(remaining)}`;
    const fill = overlay.querySelector('[data-hire-fill]') as HTMLElement | null;
    if (fill) fill.style.width = Math.min(100, (1 - remaining / dur) * 100).toFixed(1) + '%';
  }
}

interface FireDialogOpts {
  title: string;
  role: string;
  served: number;
  unitLabel: string;
  salaryStopped: number;
  severance: number;
  cash: number;
  consequence: string;
}

function showFireModal(o: FireDialogOpts): Promise<boolean> {
  return new Promise((resolve) => {
    const after = o.cash - o.severance;
    const broke = after < 0;
    const cashAfter = broke ? '$0' : formatMoney(after);
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `
      <div class="modal fire-modal" role="dialog" aria-modal="true">
        <header class="fire-modal-head">
          <div class="fire-modal-icon">${icon('warning', { size: 24 })}</div>
          <div class="fire-modal-title">
            <div class="fm-eyebrow">Termination Notice</div>
            <div class="fm-title">${o.title.replace(/^Fire\s+/, '')}</div>
          </div>
        </header>
        <div class="fire-modal-body">
          <div class="fm-section">
            <div class="fm-row"><span class="fm-key">Role</span><span class="fm-val">${o.role}</span></div>
            <div class="fm-row"><span class="fm-key">Service</span><span class="fm-val">${formatNumber(o.served)} <span class="fm-dim">${o.unitLabel}</span></span></div>
            <div class="fm-row"><span class="fm-key">Salary stop</span><span class="fm-val pos">−${formatMoney(o.salaryStopped)}/s saved</span></div>
          </div>
          <div class="fm-section fm-money">
            <div class="fm-money-line">
              <span class="fm-money-label">Severance</span>
              <span class="fm-money-val neg">−${formatMoney(o.severance)}</span>
            </div>
            <div class="fm-money-line sub">
              <span class="fm-money-label">Cash now</span>
              <span class="fm-money-val">${formatMoney(o.cash)}</span>
            </div>
            <div class="fm-money-line total ${broke ? 'broke' : ''}">
              <span class="fm-money-label">Cash after</span>
              <span class="fm-money-val">${cashAfter}${broke ? ' <span class="fm-warn-tag">capped</span>' : ''}</span>
            </div>
          </div>
          <div class="fm-impact">
            <span class="fm-impact-icon">ℹ</span>
            <span>${o.consequence}</span>
          </div>
        </div>
        <footer class="fire-modal-foot">
          <button class="modal-btn cancel" data-cancel>Cancel</button>
          <button class="modal-btn confirm danger" data-confirm>${icon('fire', { size: 12 })} Fire — Pay ${formatMoney(o.severance)}</button>
        </footer>
      </div>
    `;
    document.body.appendChild(overlay);
    requestAnimationFrame(() => overlay.classList.add('open'));

    const cleanup = (result: boolean): void => {
      document.removeEventListener('keydown', onKey);
      overlay.classList.remove('open');
      setTimeout(() => overlay.remove(), 180);
      resolve(result);
    };
    const onKey = (e: KeyboardEvent): void => {
      if (e.key === 'Escape') cleanup(false);
      else if (e.key === 'Enter') cleanup(true);
    };
    overlay.querySelector('[data-cancel]')!.addEventListener('click', () => cleanup(false));
    overlay.querySelector('[data-confirm]')!.addEventListener('click', () => cleanup(true));
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) cleanup(false);
    });
    document.addEventListener('keydown', onKey);
    (overlay.querySelector('[data-confirm]') as HTMLButtonElement).focus();
  });
}

function computePayroll(state: GameState): { manager: number; employee: number } {
  let manager = 0;
  let employee = 0;
  for (const def of INDUSTRIES) {
    const ind = state.industries[def.id];
    if (!ind) continue;
    if (ind.hasManager) manager += managerSalaryPerSec(def);
    if (ind.employees > 0) employee += employeeSalaryPerSec(def, ind.employees);
  }
  return { manager, employee };
}

function estimatedRate(state: GameState): number {
  let gross = 0;
  for (const def of INDUSTRIES) {
    const ind = state.industries[def.id]!;
    if (ind.count <= 0) continue;
    if (ind.paused) continue;                       // paused: no output
    if (!ind.hasManager && !ind.producing) continue; // idle & no manager: no output
    const rev = industryRevenue(def, state);
    const t = industryCycleTime(def, state);
    if (t > 0) gross += rev / t;
  }
  const payroll = computePayroll(state);
  return gross - payroll.manager - payroll.employee;
}

function renderIndustries(ui: UI): string {
  const cats = industryCategories();
  const active = cats.includes(ui.industryCategory) ? ui.industryCategory : (cats[0] ?? '');
  ui.industryCategory = active;
  const filtered = INDUSTRIES.filter(d => (d.category ?? 'Misc') === active);
  return `
    <div class="grid">
      ${filtered.map(def => renderIndustryCard(ui, def)).join('')}
    </div>
  `;
}

function renderIndustryCard(ui: UI, def: IndustryDef): string {
  const ind = ui.state.industries[def.id]!;
  if (!ind.unlocked) {
    const can = ui.state.money >= def.unlockCost;
    return `
      <div class="card locked ${can ? 'affordable' : ''}" data-card="${def.id}">
        <div class="card-bg"><div class="card-fill" style="width:0%"></div></div>
        <div class="card-content">
          <div class="card-head">
            <div class="icon big">${iconForEmoji(def.icon, { size: 32 })}</div>
            <div class="card-title">
              <div class="name">${def.name}</div>
              <div class="sub">${icon('lock', { size: 12 })} Locked</div>
            </div>
          </div>
          <button class="buy buy-big" data-buy="${def.id}" ${can ? '' : 'disabled'}>
            ${icon('unlock', { size: 12 })} Unlock ${formatMoney(def.unlockCost)}
          </button>
        </div>
      </div>`;
  }

  const qty = ui.buyQty === 'max'
    ? maxAffordable(def, ind.count, ui.state.money)
    : (ui.buyQty as number);
  const buyCost = ind.count === 0
    ? def.baseCost
    : costForNext(def, ind.count, Math.max(1, qty));
  const buyLabel = ind.count === 0
    ? `Buy ${formatMoney(def.baseCost)}`
    : `Buy ${qty <= 0 ? 1 : qty} · ${formatMoney(buyCost)}`;
  const canBuy = ind.count === 0
    ? ui.state.money >= def.baseCost
    : qty > 0 && ui.state.money >= buyCost;

  const rev = industryRevenue(def, ui.state);
  const cycle = industryCycleTime(def, ui.state);
  const pct = Math.max(0, Math.min(100, ind.progress * 100));
  const producing = !ind.paused && (ind.producing || ind.hasManager);
  const canProduce = ind.count > 0 && !ind.hasManager && !ind.paused;
  const milestone = unitMilestoneMultiplier(ind.count);
  const nm = nextMilestone(ind.count);
  const syn = synergyMultiplier(def, ui.state);
  const synPct = Math.round((syn - 1) * 100);
  const shopStat = ui.state.shopStats[def.id];
  const sold = shopStat?.unitsSold ?? 0;
  const salesMult = salesMilestoneMultiplier(sold);
  const empBonusPct = Math.round((employeeRevenueMultiplier(ind.employees) - 1) * 100);
  const milestoneText = milestone > 1 ? `×${milestone} units` : '';
  const synergyText = synPct > 0 ? `+${synPct}% synergy` : '';
  const salesText = salesMult > 1 ? `×${salesMult} sales` : '';
  const overtimeText = empBonusPct > 0 ? `+${empBonusPct}% overtime` : '';
  const nextText = nm.next !== null
    ? `next ×2 @ ${formatNumber(nm.next)} units (${formatNumber(nm.next - ind.count)} to go)`
    : 'max units milestone';

  return `
    <div class="card ${ind.count > 0 ? 'owned' : ''} ${ind.hasManager ? 'auto' : ''} ${canProduce ? 'clickable' : ''}"
         data-card="${def.id}" ${canProduce ? `data-start="${def.id}"` : ''}>
      <div class="card-bg"><div class="card-fill" style="width:${pct}%"></div></div>
      <div class="card-content">
        <div class="card-head">
          <div class="icon big">${iconForEmoji(def.icon, { size: 32 })}</div>
          <div class="card-title">
            <div class="name">${def.name} <span class="count">×${formatNumber(ind.count)}</span></div>
            <div class="sub">
              <span class="sub-rate">${formatMoney(rev / Math.max(0.0001, cycle))}/s</span>
              <span class="sub-dot">·</span>
              <span>${formatMoney(rev)} / cycle</span>
              <span class="sub-dot">·</span>
              <span>${formatTime(cycle)}</span>
            </div>
            ${(milestoneText || synergyText || salesText || overtimeText || ind.count > 0) ? `
              <div class="sub bonuses">
                ${milestoneText ? `<span class="bonus-tag milestone">${milestoneText}</span>` : ''}
                ${salesText ? `<span class="bonus-tag sales">${salesText}</span>` : ''}
                ${synergyText ? `<span class="bonus-tag synergy">${synergyText}</span>` : ''}
                ${overtimeText ? `<span class="bonus-tag overtime">${overtimeText}</span>` : ''}
                ${ind.count > 0 ? `<span class="bonus-next">${nextText}</span>` : ''}
              </div>
            ` : ''}
          </div>
          <div class="status">
            <div class="status-rev">+${formatMoney(rev)}</div>
            <div class="status-time">${ind.paused ? `${icon('pause', { size: 11 })} Paused` : producing ? formatTime((1 - ind.progress) * cycle) + ' left' : ind.count > 0 ? '' : 'Buy units first'}</div>
          </div>
        </div>
        ${sold > 0 || ind.count > 0 ? renderSoldBadge(sold) : ''}
        <div class="card-actions">
          <button class="buy" data-buy="${def.id}" ${canBuy ? '' : 'disabled'}>
            ${buyLabel}
          </button>
          <button class="buy staff-btn" data-staff="${def.id}" title="Manage staff, salaries, pause">
            <span class="staff-btn-icons">${icon('manager', { size: 14 })}${icon('worker', { size: 14 })}</span> STAFF
            ${renderHirePips(def, ind, ui.state.money)}
          </button>
        </div>
      </div>
    </div>`;
}

function renderHirePips(def: IndustryDef, ind: IndustryState, money: number): string {
  const a = hireAvailability(def, ind, money);
  const mgrCls = ind.hasManager ? 'owned' : a.mgr ? 'on' : '';
  const empCls = ind.employees >= employeeMaxFor(def) ? 'owned' : a.emp ? 'on' : '';
  const mgrTitle = ind.hasManager ? 'Manager hired — auto-producing' : 'Manager hire available';
  const empTitle = ind.employees >= employeeMaxFor(def) ? 'Max staff hired' : 'Employee hire available';
  return `<span class="hire-pips" data-hire-pips="${def.id}">
    <span class="pip mgr ${mgrCls}" title="${mgrTitle}">${ind.hasManager ? icon('check', { size: 10 }) : icon('manager', { size: 10 })}</span>
    <span class="pip emp ${empCls}" title="${empTitle}">${ind.employees >= employeeMaxFor(def) ? icon('check', { size: 10 }) : icon('worker', { size: 10 })}${ind.employees > 0 ? `<span class="pip-num">${ind.employees}</span>` : ''}</span>
  </span>`;
}

function renderSoldBadge(sold: number): string {
  const cur = currentSalesMilestone(sold);
  const next = nextSalesMilestone(sold);
  const prevUnits = cur ? cur.units : 0;
  const tierLabel = cur ? cur.label : 'New shop';
  const tierMult = cur ? cur.mult : 1;
  let pct = 100;
  let remainStr = 'MAX TIER';
  let nextStr = '';
  if (next && next.next !== null) {
    const span = next.next - prevUnits;
    pct = Math.max(0, Math.min(100, ((sold - prevUnits) / span) * 100));
    remainStr = `${formatNumber(next.next - sold)} to go`;
    nextStr = `→ ×${next.mult} "${next.label}"`;
  } else {
    pct = 100;
  }
  return `
    <div class="sold-badge ${cur ? 'tiered' : ''}" title="Cumulative units sold across all customers">
      <div class="sb-head">
        <span class="sb-icon">${icon('package', { size: 12 })}</span>
        <span class="sb-count">${formatNumber(sold)}</span>
        <span class="sb-label">sold</span>
        ${cur ? `<span class="sb-tier">×${tierMult} · ${tierLabel}</span>` : ''}
      </div>
      <div class="sb-bar"><div class="sb-fill" style="width:${pct.toFixed(1)}%"></div></div>
      <div class="sb-foot">
        <span class="sb-next">${nextStr || 'Top tier reached'}</span>
        <span class="sb-remain">${remainStr}</span>
      </div>
    </div>
  `;
}

function renderStaffPanelBody(ui: UI, def: IndustryDef): string {
  const ind = ui.state.industries[def.id]!;
  const owned = ind.hasManager;
  const canM = ui.state.money >= def.managerCost;
  const emp = ind.employees;
  const empCap = employeeMaxFor(def);
  const empMax = emp >= empCap;
  const empCost = employeeCost(def, emp);
  const hiring = ind.hiringUntil !== null;
  const canE = !empMax && !hiring && ui.state.money >= empCost;
  const speedup = Math.round((1 - employeeSpeedMultiplier(emp)) * 100);
  const overtime = emp > EMPLOYEE_SPEED_FLOOR_AT;
  const overtimeBonus = Math.round((employeeRevenueMultiplier(emp) - 1) * 100);
  const hireDur = employeeHireDuration(emp);
  const remaining = hiring ? Math.max(0, (ind.hiringUntil! - Date.now()) / 1000) : 0;
  const empLabel = empMax
    ? `${icon('check', { size: 12 })} Max staff`
    : hiring
      ? `⏳ Hiring · ${formatTime(remaining)}`
      : `${icon('worker', { size: 12 })}+1 · ${formatMoney(empCost)} · ${formatTime(hireDur)}`;
  const mgrSalary = managerSalaryPerSec(def);
  const empSalary = employeeSalaryPerSec(def, emp);
  const totalSalary = (owned ? mgrSalary : 0) + empSalary;
  const mgrSev = managerSeverance(def, ui.state);
  const empSev = employeeSeverance(def, ui.state);

  return `
    <div class="staff-panel" data-staff-row="${def.id}">
      <div class="row-sub">
        <span class="staff-tag">${icon('manager', { size: 12 })} ${owned ? 'Manager hired' : 'No manager'}</span>
        <span class="staff-tag">${icon('worker', { size: 12 })} ${emp}/${empCap} · −${speedup}% time</span>
        ${overtime ? `<span class="staff-tag overtime-tag" title="Past speed floor — extra crew now adds revenue instead of speed">${icon('bolt', { size: 12 })} +${overtimeBonus}% overtime rev</span>` : ''}
        ${hiring ? `<span class="staff-tag hiring-tag">⏳ Recruiting…</span>` : ''}
        ${ind.paused ? `<span class="staff-tag paused-tag">${icon('pause', { size: 11 })} Paused</span>` : ''}
      </div>
      <div class="row-sub salary-row">
        <span class="staff-tag salary-tag" title="Total payroll per second">
          ${icon('salary', { size: 12 })} SALARY ${formatMoney(totalSalary)}/s
        </span>
        ${owned ? `<span class="staff-tag salary-sub">${icon('manager', { size: 12 })} ${formatMoney(mgrSalary)}/s · ${formatNumber(ind.managerProductsServed)} served</span>` : ''}
        ${emp > 0 ? `<span class="staff-tag salary-sub">${icon('worker', { size: 12 })} ${formatMoney(empSalary)}/s · ${formatNumber(ind.employeeProductsServed)} served</span>` : ''}
      </div>
      ${hiring ? `<div class="hire-bar"><div class="hire-fill" data-hire-fill="${def.id}" style="width:${Math.min(100, (1 - remaining / hireDur) * 100).toFixed(1)}%"></div></div>` : ''}
      <div class="staff-actions modal-staff-actions">
        <button class="buy" data-manager="${def.id}" ${owned || !canM ? 'disabled' : ''}>
          ${owned ? `${icon('check', { size: 12 })} Manager` : `${icon('manager', { size: 12 })} Hire Manager · ${formatMoney(def.managerCost)}`}
        </button>
        <button class="buy" data-employee="${def.id}" ${empMax || !canE ? 'disabled' : ''}>
          ${empLabel}
        </button>
        <button class="buy pause" data-pause="${def.id}" title="${ind.paused ? 'Resume production' : 'Pause production (salaries still paid)'}">
          ${ind.paused ? `${icon('play', { size: 12 })} RESUME PRODUCTION` : `${icon('pause', { size: 12 })} PAUSE PRODUCTION`}
        </button>
        ${owned ? `<button class="buy danger" data-fire-manager="${def.id}" title="Fire manager · severance ${formatMoney(mgrSev)}">
          ${icon('fire', { size: 12 })} FIRE ${icon('manager', { size: 12 })} · ${formatMoney(mgrSev)}
        </button>` : ''}
        ${emp > 0 ? `<button class="buy danger" data-fire-employee="${def.id}" title="Fire one employee · severance ${formatMoney(empSev)}">
          ${icon('fire', { size: 12 })} FIRE ${icon('worker', { size: 12 })} · ${formatMoney(empSev)}
        </button>` : ''}
        ${(owned || emp > 0) ? `<button class="buy danger fire-all" data-fire-all="${def.id}" title="Fire manager + all employees · severance ${formatMoney((owned ? mgrSev : 0) + empSev * emp)}">
          ${icon('fire', { size: 12 })}${icon('fire', { size: 12 })} FIRE ALL · ${formatMoney((owned ? mgrSev : 0) + empSev * emp)}
        </button>` : ''}
      </div>
    </div>
  `;
}

function openStaffModal(ui: UI, root: HTMLElement, defId: string): void {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return;
  // close any existing
  document.querySelectorAll('.modal-overlay.staff-overlay').forEach(el => el.remove());
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay staff-overlay';
  overlay.innerHTML = `
    <div class="modal staff-modal" role="dialog" aria-modal="true">
      <header class="fire-modal-head staff-modal-head">
        <div class="fire-modal-icon staff-modal-icon">${iconForEmoji(def.icon, { size: 24 })}</div>
        <div class="fire-modal-title">
          <div class="fm-eyebrow">Manage Staff</div>
          <div class="fm-title">${def.name}</div>
        </div>
        <button class="modal-close" data-close aria-label="Close">×</button>
      </header>
      <div class="fire-modal-body staff-modal-body">${renderStaffPanelBody(ui, def)}</div>
    </div>`;
  document.body.appendChild(overlay);
  openStaffDefId = defId;
  openStaffWasHiring = ui.state.industries[defId]?.hiringUntil != null;
  requestAnimationFrame(() => overlay.classList.add('open'));

  const refresh = (): void => {
    const body = overlay.querySelector('.staff-modal-body') as HTMLElement | null;
    if (body) body.innerHTML = renderStaffPanelBody(ui, def);
    attachStaffModalHandlers(ui, root, overlay, def, refresh);
  };
  openStaffRefresh = refresh;
  const close = (): void => {
    openStaffDefId = null;
    openStaffRefresh = null;
    openStaffWasHiring = false;
    overlay.classList.remove('open');
    setTimeout(() => overlay.remove(), 180);
    document.removeEventListener('keydown', onKey);
  };
  const onKey = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') close();
  };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) close();
  });
  overlay.querySelector('[data-close]')!.addEventListener('click', close);
  attachStaffModalHandlers(ui, root, overlay, def, refresh);
}

function attachStaffModalHandlers(
  ui: UI, root: HTMLElement, overlay: HTMLElement, def: IndustryDef, refresh: () => void
): void {
  const q = (sel: string): HTMLElement | null => overlay.querySelector(sel);
  const mgrBtn = q('[data-manager]');
  if (mgrBtn) mgrBtn.addEventListener('click', () => {
    if (buyManager(ui.state, def.id)) {
      ui.notify(`Hired manager for ${def.name}`, { color: categoryColor(def.category) });
      save(ui.state); renderAll(ui, root); refresh();
    }
  });
  const empBtn = q('[data-employee]');
  if (empBtn) empBtn.addEventListener('click', () => {
    if (hireEmployee(ui.state, def.id)) {
      save(ui.state); renderAll(ui, root); refresh();
    }
  });
  const pauseBtn = q('[data-pause]');
  if (pauseBtn) pauseBtn.addEventListener('click', () => {
    const nowPaused = toggleProductionPaused(ui.state, def.id);
    ui.notify(`${def.name} ${nowPaused ? `${icon('pause', { size: 11 })} paused` : `${icon('play', { size: 11 })} resumed`}`, { color: categoryColor(def.category) });
    save(ui.state); renderAll(ui, root); refresh();
  });
  const fmBtn = q('[data-fire-manager]');
  if (fmBtn) fmBtn.addEventListener('click', async () => {
    const indState = ui.state.industries[def.id]!;
    const sev = managerSeverance(def, ui.state);
    const ok = await showFireModal({
      title: `Fire Manager — ${def.name}`,
      role: `${icon('manager', { size: 12 })} Manager`,
      served: indState.managerProductsServed,
      unitLabel: 'products produced under their watch',
      salaryStopped: managerSalaryPerSec(def),
      severance: sev,
      cash: ui.state.money,
      consequence: 'Production stops — you must click each cycle manually until rehired.'
    });
    if (!ok) return;
    const paid = fireManager(ui.state, def.id);
    ui.notify(`${icon('manager', { size: 12 })} Manager fired at ${def.name} · severance ${formatMoney(paid)}`, { color: categoryColor(def.category) });
    save(ui.state); renderAll(ui, root); refresh();
  });
  const feBtn = q('[data-fire-employee]');
  if (feBtn) feBtn.addEventListener('click', async () => {
    const indState = ui.state.industries[def.id]!;
    const sev = employeeSeverance(def, ui.state);
    const empCount = indState.employees;
    const sharePer = empCount > 0 ? indState.employeeProductsServed / empCount : 0;
    const newSpeedup = Math.round((1 - employeeSpeedMultiplier(empCount - 1)) * 100);
    const oldSpeedup = Math.round((1 - employeeSpeedMultiplier(empCount)) * 100);
    const ok = await showFireModal({
      title: `Fire Employee — ${def.name}`,
      role: `${icon('worker', { size: 12 })} Employee (1 of ${empCount})`,
      served: Math.floor(sharePer),
      unitLabel: 'avg products attributable to their share',
      salaryStopped: employeeSalaryPerSec(def, 1),
      severance: sev,
      cash: ui.state.money,
      consequence: `Cycle speedup drops from −${oldSpeedup}% → −${newSpeedup}%.`
    });
    if (!ok) return;
    const paid = fireEmployee(ui.state, def.id);
    ui.notify(`${icon('worker', { size: 12 })} Employee fired at ${def.name} · severance ${formatMoney(paid)}`, { color: categoryColor(def.category) });
    save(ui.state); renderAll(ui, root); refresh();
  });
  const faBtn = q('[data-fire-all]');
  if (faBtn) faBtn.addEventListener('click', async () => {
    const indState = ui.state.industries[def.id]!;
    const mgrSev = indState.hasManager ? managerSeverance(def, ui.state) : 0;
    const empSev = indState.employees > 0 ? employeeSeverance(def, ui.state) * indState.employees : 0;
    const total = mgrSev + empSev;
    const totalSalary = (indState.hasManager ? managerSalaryPerSec(def) : 0)
      + employeeSalaryPerSec(def, indState.employees);
    const totalServed = indState.managerProductsServed + indState.employeeProductsServed;
    const roleParts: string[] = [];
    if (indState.hasManager) roleParts.push(`${icon('manager', { size: 12 })} Manager`);
    if (indState.employees > 0) roleParts.push(`${icon('worker', { size: 12 })} ${indState.employees} Employee${indState.employees > 1 ? 's' : ''}`);
    const ok = await showFireModal({
      title: `Fire ALL Staff — ${def.name}`,
      role: roleParts.join(' + '),
      served: totalServed,
      unitLabel: 'total products produced under entire staff',
      salaryStopped: totalSalary,
      severance: total,
      cash: ui.state.money,
      consequence: 'Production halts entirely. You will need to re-hire and wait through recruiting timers.'
    });
    if (!ok) return;
    const paid = fireAll(ui.state, def.id);
    ui.notify(`${icon('fire', { size: 12 })}${icon('fire', { size: 12 })} All staff fired at ${def.name} · severance ${formatMoney(paid)}`, { color: categoryColor(def.category) });
    save(ui.state); renderAll(ui, root); refresh();
  });
}

function upgradeIconFor(industryId: string, size = 18): string {
  if (industryId === 'global') return icon('globe', { size });
  if (industryId === 'customer') return icon('people', { size });
  const ind = INDUSTRIES_BY_ID.get(industryId);
  return ind ? iconForEmoji(ind.icon, { size }) : icon('bolt', { size });
}

function upgradeTarget(industryId: string): string {
  if (industryId === 'global') return 'All industries';
  if (industryId === 'customer') return 'Customers';
  const ind = INDUSTRIES_BY_ID.get(industryId);
  return ind ? ind.name : '—';
}

function upgradeDescription(u: typeof UPGRADES[number]): string {
  if (u.desc) return u.desc;
  const kind = u.kind ?? 'revenue';
  const v = u.value ?? 0;
  switch (kind) {
    case 'revenue':        return `×${u.multiplier ?? 1} revenue`;
    case 'spawn_rate':     return `×${v} customer flow`;
    case 'walk_speed':     return `×${v} walk speed`;
    case 'shop_dwell':     return `×${v} dwell time`;
    case 'wealthy_rate':   return `+${Math.round(v * 100)}% wealthy chance`;
    case 'whale_rate':     return `+${Math.round(v * 100)}% whale chance`;
    case 'tip_mult':       return `×${v} all tips`;
    case 'whale_tip':      return `×${v} whale tips`;
    case 'rep_gain_mult':  return `×${v} rep gained`;
    case 'rep_loss_mult':  return `×${v} rep / $ loss`;
    case 'partial_forgive': return `Partial orders forgiven`;
    case 'rep_regen':      return `+${v} rep / sec`;
  }
  return '';
}

function renderUpgrades(ui: UI): string {
  const available = UPGRADES.filter(u => {
    if (ui.state.upgrades[u.id]) return false;
    if (u.industryId === 'global' || u.industryId === 'customer') return true;
    const ind = ui.state.industries[u.industryId];
    if (!ind || !ind.unlocked) return false;
    if (u.requires && ind.count < u.requires) return false;
    return true;
  });
  const owned = UPGRADES.filter(u => ui.state.upgrades[u.id]);

  const upRow = (id: string, name: string, _iconHtml: string, sub: string, cost: number | null, isOwned: boolean, can: boolean): string => `
    <div class="upgrade-row ${isOwned ? 'owned' : ''}" title="${sub.replace(/"/g, '&quot;')}">
      <div class="ur-name">${name}</div>
      <div class="ur-sub">${sub}</div>
      ${isOwned
        ? `<span class="ur-owned" title="Owned">${icon('check', { size: 14 })}</span>`
        : `<button class="ur-buy" data-upgrade="${id}" ${can ? '' : 'disabled'}>${formatMoney(cost!)}</button>`}
    </div>`;

  const groupOrder = [ui.upgradeGroup] as const;
  const groupLabel: Record<string, string> = {
    customer: `${icon('people', { size: 14 })} Customers`,
    global: `${icon('globe', { size: 14 })} Global`,
    industry: `${icon('factory', { size: 14 })} Industries`
  };
  const groupOf = (u: typeof UPGRADES[number]) =>
    u.industryId === 'customer' ? 'customer'
    : u.industryId === 'global' ? 'global'
    : 'industry';

  const renderGroup = (label: string, items: typeof UPGRADES, isOwned: boolean): string => {
    if (items.length === 0) return '';
    const rows = items.map(u => {
      const ic = upgradeIconFor(u.industryId, 18);
      const target = upgradeTarget(u.industryId);
      const sub = `${target} · ${upgradeDescription(u)}`;
      const can = ui.state.money >= u.cost;
      return upRow(u.id, u.name, ic, sub, isOwned ? null : u.cost, isOwned, can);
    }).join('');
    return `<h4 class="section-sub">${label}</h4><div class="upgrade-grid">${rows}</div>`;
  };

  const buildSections = (items: typeof UPGRADES, isOwned: boolean): string => {
    if (items.length === 0) return '';
    return groupOrder.map(g => {
      const subset = items.filter(u => groupOf(u) === g);
      return renderGroup(groupLabel[g]!, subset, isOwned);
    }).join('');
  };

  return `
    <h3 class="section">Available (${available.length})</h3>
    ${available.length ? buildSections(available, false) : '<div class="empty-placeholder">No upgrades available. Buy more units to unlock.</div>'}
    <h3 class="section">Owned (${owned.length})</h3>
    ${owned.length ? buildSections(owned, true) : '<div class="empty-placeholder">None yet.</div>'}
  `;
}

// patch a single card in place — replaces just one <div data-card="id">
// without rebuilding the whole grid. cheaper than renderAll for one-card mutations.
function patchCard(ui: UI, root: HTMLElement, defId: string): void {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return;
  const existing = root.querySelector(`[data-card="${defId}"]`) as HTMLElement | null;
  if (!existing) return;
  const tpl = document.createElement('template');
  tpl.innerHTML = renderIndustryCard(ui, def).trim();
  const fresh = tpl.content.firstElementChild;
  if (fresh) existing.replaceWith(fresh);
}

// returns true if a buy mutation flipped unlock state (sidebar count needs full refresh)
function buyAndDetectUnlock(ui: UI, defId: string): { bought: number; unlockChanged: boolean } {
  const ind = ui.state.industries[defId];
  const wasUnlocked = !!ind?.unlocked;
  const wasCountZero = (ind?.count ?? 0) === 0;
  const result = buyIndustry(ui.state, defId, ui.buyQty);
  const nowUnlocked = !!ui.state.industries[defId]?.unlocked;
  const nowOwned = (ui.state.industries[defId]?.count ?? 0) > 0;
  const unlockChanged = wasUnlocked !== nowUnlocked || (wasCountZero && nowOwned);
  return { bought: result.bought, unlockChanged };
}

function _attachMainHandlersImpl(ui: UI, root: HTMLElement): void {
  const main = root.querySelector('#main') as HTMLElement;
  // single delegated click handler — survives single-card patches without rebinding
  main.addEventListener('click', (e) => {
    const t = e.target as HTMLElement;
    const subtabBtn = t.closest('[data-subtab]') as HTMLElement | null;
    if (subtabBtn) {
      ui.industryCategory = subtabBtn.dataset.subtab!;
      renderAll(ui, root);
      return;
    }
    const buyBtn = t.closest('[data-buy]') as HTMLElement | null;
    if (buyBtn) {
      e.stopPropagation();
      const id = buyBtn.dataset.buy!;
      const r = buyAndDetectUnlock(ui, id);
      if (r.bought > 0) {
        save(ui.state);
        if (r.unlockChanged) renderAll(ui, root);
        else patchCard(ui, root, id);
      }
      return;
    }
    const staffBtn = t.closest('[data-staff]') as HTMLElement | null;
    if (staffBtn) {
      e.stopPropagation();
      const id = staffBtn.dataset.staff!;
      const pip = t.closest('.pip') as HTMLElement | null;
      if (pip && pip.classList.contains('on')) {
        const def = INDUSTRIES_BY_ID.get(id);
        const color = categoryColor(def?.category);
        if (pip.classList.contains('mgr')) {
          if (buyManager(ui.state, id)) {
            ui.notify(`Hired manager${def ? ' for ' + def.name : ''}`, { color });
            save(ui.state); patchCard(ui, root, id);
          }
        } else if (pip.classList.contains('emp')) {
          if (hireEmployee(ui.state, id)) {
            save(ui.state); patchCard(ui, root, id);
          }
        }
        return;
      }
      openStaffModal(ui, root, id);
      return;
    }
    const upBtn = t.closest('[data-upgrade]') as HTMLElement | null;
    if (upBtn) {
      const id = upBtn.dataset.upgrade!;
      if (buyUpgrade(ui.state, id)) {
        const u = UPGRADES_BY_ID.get(id);
        const def = u && u.industryId !== 'global' && u.industryId !== 'customer'
          ? INDUSTRIES_BY_ID.get(u.industryId)
          : undefined;
        ui.notify(`${icon('bolt', { size: 12 })} ${u?.name ?? 'Upgrade'} purchased`, { color: categoryColor(def?.category) });
        save(ui.state);
        renderAll(ui, root);
      }
      return;
    }
    const startEl = t.closest('[data-start]') as HTMLElement | null;
    if (startEl) {
      e.stopPropagation();
      const id = startEl.dataset.start!;
      if (startProduction(ui.state, id)) {
        patchCard(ui, root, id);
      }
      return;
    }
  });
}

// idempotent guard so renderAll's re-attach doesn't double-bind the delegated handler
let _mainHandlersBound: HTMLElement | null = null;

function attachMainHandlers(ui: UI, root: HTMLElement): void {
  const main = root.querySelector('#main') as HTMLElement;
  if (_mainHandlersBound === main) return;
  _mainHandlersBound = main;
  _attachMainHandlersImpl(ui, root);
}
