import './styles.css';
import { defaultState, migrateState, offlineProgress, resolveHires, tick, INDUSTRIES_BY_ID } from './game';
import { load, save, isWiping } from './save';
import { mountUI } from './ui';
import { Market } from './market';
import { formatMoney } from './format';
import { notify, onLog, type LogEntry } from './log';
import { categoryColor } from './categories';
import { icon } from './icons';

const loaded = load();
const state = loaded ? migrateState(loaded) : defaultState();

const offline = loaded ? offlineProgress(state, Date.now()) : 0;

const ui = mountUI(state, notify);
const uiTick = ui.tick;

const logPanel = document.createElement('section');
logPanel.className = 'log-panel';
logPanel.innerHTML = `
  <header class="log-head">
    <span class="log-title">${icon('scroll', { size: 14 })} LOG</span>
    <button class="log-clear" type="button" title="Clear log">${icon('x', { size: 14 })}</button>
  </header>
  <div class="log-body" id="log-body"></div>
`;
const leftSidebar = document.getElementById('left-sidebar');
(leftSidebar ?? document.body).appendChild(logPanel);
const logBody = logPanel.querySelector('#log-body') as HTMLElement;
const LOG_CAP = 100;

function pad2(n: number): string { return n < 10 ? '0' + n : String(n); }
function fmtTs(ts: number): string {
  const d = new Date(ts);
  return pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds());
}

function appendLog(e: LogEntry): void {
  const row = document.createElement('div');
  row.className = 'log-entry' + (e.color ? ' tinted' : '');
  if (e.color) row.style.setProperty('--log-color', e.color);
  row.innerHTML = `<span class="log-ts">${fmtTs(e.ts)}</span><span class="log-msg">${e.msg}</span>`;
  logBody.appendChild(row);
  while (logBody.childElementCount > LOG_CAP) logBody.firstElementChild?.remove();
  logBody.scrollTop = logBody.scrollHeight;
  requestAnimationFrame(() => row.classList.add('in'));
}

onLog(appendLog);
(logPanel.querySelector('.log-clear') as HTMLButtonElement).addEventListener('click', () => {
  logBody.innerHTML = '';
});

const scene = new Market(state);
scene.onShopClick = (defId) => {
  const def = INDUSTRIES_BY_ID.get(defId);
  if (!def) return;
  ui.ui.tab = 'industries';
  ui.ui.industryCategory = def.category ?? 'Misc';
  document.querySelectorAll('.tab').forEach(b => {
    b.classList.toggle('active', (b as HTMLElement).dataset.tab === 'industries');
  });
  ui.render();
  requestAnimationFrame(() => {
    const card = document.querySelector(`[data-card="${defId}"]`) as HTMLElement | null;
    if (!card) return;
    card.scrollIntoView({ behavior: 'smooth', block: 'center' });
    card.classList.remove('flash');
    requestAnimationFrame(() => card.classList.add('flash'));
    setTimeout(() => card.classList.remove('flash'), 1400);
  });
};

if (offline > 0) {
  notify(`Welcome back! Earned ${formatMoney(offline)} while away.`);
}

// game loop — uses DOM-mutation tick (no innerHTML rewrite),
// so user clicks/inputs are never interrupted mid-gesture.
let last = performance.now();
function loop(now: number): void {
  const dt = Math.min(1, (now - last) / 1000);
  last = now;
  const result = tick(state, dt);
  const hired = resolveHires(state);
  state.lastTick = Date.now();
  uiTick();
  if (hired.length > 0) {
    for (const id of hired) {
      const def = INDUSTRIES_BY_ID.get(id);
      if (def) notify(`${icon('worker', { size: 12 })} New employee joined ${def.name}`, { color: categoryColor(def.category) });
    }
    ui.render();
  }
  for (const defId in result.completions) {
    scene.flyProduct(defId, result.completions[defId]!);
  }
  requestAnimationFrame(loop);
}

requestAnimationFrame((t) => { last = t; loop(t); });

// auto save every 10s
setInterval(() => { if (!isWiping()) save(state); }, 10_000);
window.addEventListener('beforeunload', () => { if (!isWiping()) save(state); });

// ArcadeDeck 통합 전송 규격
function postScore(): void {
  try {
    window.parent.postMessage({
      type: 'GAME_OVER',
      score: Math.floor(state.totalEarned),   // 주 점수 (score 필드 필수)
      subScore: Math.floor(state.totalProduced) // 보조 점수 (subScore 필드 권장)
    }, '*');
  } catch { /* ignore */ }
}
setInterval(postScore, 5_000);
window.addEventListener('beforeunload', postScore);
window.addEventListener('pagehide', postScore);

try { localStorage.removeItem('scene-kind'); } catch { /* ignore */ }
