export const CATEGORY_COLORS: Record<string, string> = {
  Food:          '#ff6b6b',
  Lifestyle:     '#ff9ff3',
  Agriculture:   '#6ab04c',
  Health:        '#4bcffa',
  Entertainment: '#f368e0',
  'Real Estate': '#c4a373',
  Tech:          '#5dade2',
  Finance:       '#f5cd79',
  Travel:        '#74b9ff',
  Energy:        '#feca57',
  Misc:          '#9aa4b2'
};

export function categoryColor(category: string | undefined | null): string | undefined {
  if (!category) return undefined;
  return CATEGORY_COLORS[category];
}
