const escapeHtml = (s: string): string =>
  s.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]!));

export function icon(key: string, opts: IconOpts = {}): string {
  const body = SVG[key] ?? SVG.dot;
  const sz = opts.size ?? 16;
  const cls = `icon${opts.cls ? ' ' + opts.cls : ''}`;
  const title = opts.title ? `<title>${escapeHtml(opts.title)}</title>` : '';
  const aria = opts.title ? `role="img" aria-label="${escapeHtml(opts.title)}"` : 'aria-hidden="true"';
  return `<svg class="${cls}" xmlns="http://www.w3.org/2000/svg" width="${sz}" height="${sz}" viewBox="0 0 24 24" ${aria}>${title}${body}</svg>`;
}

export function iconForEmoji(emoji: string, opts: IconOpts = {}): string {
  const key = EMOJI_TO_KEY[emoji.trim()] ?? 'dot';
  return icon(key, opts);
}

export function hasIconFor(emoji: string): boolean {
  return EMOJI_TO_KEY[emoji.trim()] !== undefined;
}
