interface Shop {
  el: HTMLElement;
  badgeEl: HTMLElement;
  statsEl: HTMLElement;
  x: number;       // center px from left of street
  floor: number;   // 0 = ground, 1 = second story, etc.
  defId: string;
}

const FLOOR_H = 130;
const STAIR_W = 90;       // horizontal extent of diagonal stair zigzag
const SIDE_PAD = 20;
const SHOP_GAP = 40;
// fixed shop capacity per floor (ground→top). overflow spills to repeating last cap.
const FLOOR_CAPS = [10, 8, 6, 6];
function floorCap(f: number): number {
  return FLOOR_CAPS[f] ?? FLOOR_CAPS[FLOOR_CAPS.length - 1]!;
}
function floorIndexForShop(i: number): { floor: number; idxInFloor: number } {
  let remaining = i;
  let f = 0;
  while (true) {
    const cap = floorCap(f);
    if (remaining < cap) return { floor: f, idxInFloor: remaining };
    remaining -= cap;
    f++;
  }
}
function floorsRequired(n: number): number {
  if (n <= 0) return 1;
  let f = 0;
  let placed = 0;
  while (placed < n) {
    placed += floorCap(f);
    f++;
  }
  return f;
}
const GROUND_H = 40;
const CLIMB_SPEED = 110;  // px / sec along stair

type WealthTier = 'broke' | 'normal' | 'wealthy' | 'whale';

interface Wealth {
  tier: WealthTier;
  multiplier: number;   // applied to tip + penalty
  units: number;        // how many products they want to buy
  icon: string;         // badge icon
}

interface Customer {
  el: HTMLElement;
  body: HTMLElement;
  product: HTMLElement;
  x: number;
  y: number;       // px lifted above ground walking line
  vx: number;      // px/sec
  target: Shop | null;
  route: Shop[];   // ordered shops customer plans to visit this trip
  routeIdx: number;
  state: 'walking-in' | 'climbing-up' | 'shopping' | 'walking-out' | 'climbing-down';
  shopTimer: number;
  facing: 1 | -1;
  wealth: Wealth;
  floor: number;   // floor customer currently stands on
  lane: number;    // 0 = front (closer to camera), 1 = back. Drives y-sort: lift, scale, z-index.
  baseScale: number;
  side: 'L' | 'R'; // stair side this customer uses
}

// tier index = position in INDUSTRIES list (definitions are tier-ordered by baseRevenue).
// drives demand curve: customers prefer shops that match their wealth.
const TIER_INDEX: Map<string, number> = new Map(INDUSTRIES.map((d, i) => [d.id, i]));

function demandWeight(tier: WealthTier, tierIdx: number, maxTierIdx: number): number {
  const t = maxTierIdx > 0 ? tierIdx / maxTierIdx : 0;
  switch (tier) {
    // broke still mostly hits low-tier, small chance to wander upmarket
    case 'broke':   return (1 - t) * (1 - t) * 0.9 + 0.1;
    // normal peaks just-below-middle; flat enough that any unlocked shop sees traffic
    case 'normal':  return Math.max(0.25, 1 - 0.7 * Math.abs(t - 0.4));
    // wealthy: linear ramp, top tier ~10x bottom
    case 'wealthy': return 0.15 + 1.6 * t;
    // whale: quadratic, top tier ~30x bottom — strongly pulls demand off lemonade
    case 'whale':   return 0.08 + 3 * t * t;
  }
}

function weightedPick<T>(items: T[], weights: number[]): number {
  let sum = 0;
  for (const w of weights) sum += w;
  if (!(sum > 0)) return Math.floor(Math.random() * items.length);
  let r = Math.random() * sum;
  for (let i = 0; i < weights.length; i++) {
    r -= weights[i]!;
    if (r <= 0) return i;
  }
  return items.length - 1;
}

function rollWealth(rep: number, wealthyBonus: number, whaleBonus: number): Wealth {
  // distribution shifts with reputation; upgrades add absolute prob to wealthy/whale.
  // bonuses steal from broke first, then normal (the implicit residual).
  const t = (rep - 1) / 999;
  let pBroke   = Math.max(0, 0.50 - 0.45 * t);
  let pWhale   = Math.max(0, Math.min(0.95, 0.10 * t + whaleBonus));
  let pWealthy = Math.max(0, Math.min(0.95, 0.05 + 0.30 * t + wealthyBonus));
  // wealthy/whale bonus first absorbs pBroke (poor → rich shift), residual eats pNormal.
  const baseWhale   = 0.10 * t;
  const baseWealthy = 0.05 + 0.30 * t;
  const bonusAdded = Math.max(0, (pWhale - baseWhale) + (pWealthy - baseWealthy));
  pBroke = Math.max(0, pBroke - bonusAdded);
  // if still over budget (pBroke=0 + huge bonuses), scale wealthy/whale down proportionally.
  const sum = pBroke + pWhale + pWealthy;
  if (sum > 1) {
    const scale = (1 - pBroke) / (pWhale + pWealthy);
    pWhale   *= scale;
    pWealthy *= scale;
  }
  const r = Math.random();
  if (r < pBroke) {
    return { tier: 'broke', multiplier: 0.3, units: 1, icon: 'coin' };
  }
  if (r < pBroke + pWhale) {
    return { tier: 'whale', multiplier: 8, units: 3 + Math.floor(Math.random() * 3), icon: 'crown' };
  }
  if (r < pBroke + pWhale + pWealthy) {
    return { tier: 'wealthy', multiplier: 2.5, units: 1 + Math.floor(Math.random() * 2), icon: 'gem' };
  }
  return { tier: 'normal', multiplier: 1, units: 1, icon: '' };
}

export class Market {
  onShopClick?: (defId: string) => void;
  private root: HTMLElement;
  private street: HTMLElement;
  private shopsRow: HTMLElement;
  private peopleLayer: HTMLElement;
  private shops: Map<string, Shop> = new Map();
  private openShops: Shop[] = [];
  private customers: Customer[] = [];
  private parcelQueue: Map<string, { pending: number; active: boolean }> = new Map();
  private spawnAcc = 0;
  private lastT = performance.now();
  private state: GameState;
  private width = 0;
  private rafId = 0;
  private alive = true;
  private resizeHandler: () => void;
  private stairEl: HTMLElement;
  private stairElR!: HTMLElement;
  private slabsEl!: HTMLElement;
  private floors = 1;
  // left stair strip (outer=far from shops, inner=near shops)
  private stairXL = 0;
  private stairXR = 0;
  // right stair strip
  private stairXL_R = 0;
  private stairXR_R = 0;

  private stairInner(side: 'L' | 'R'): number {
    return side === 'L' ? this.stairXR : this.stairXL_R;
  }
  private stairOuter(side: 'L' | 'R'): number {
    return side === 'L' ? this.stairXL : this.stairXR_R;
  }
  private stairBottomX(flight: number, side: 'L' | 'R' = 'L'): number {
    return flight % 2 === 0 ? this.stairInner(side) : this.stairOuter(side);
  }
  private stairTopX(flight: number, side: 'L' | 'R' = 'L'): number {
    return flight % 2 === 0 ? this.stairOuter(side) : this.stairInner(side);
  }
  private climbX(flight: number, y: number, side: 'L' | 'R' = 'L'): number {
    const t = Math.max(0, Math.min(1, (y - flight * FLOOR_H) / FLOOR_H));
    return this.stairBottomX(flight, side) + (this.stairTopX(flight, side) - this.stairBottomX(flight, side)) * t;
  }
  private floorScale(floor: number): number {
    // softer exponential falloff (~12% per floor); clamp 0.55 — upper floors still readable but clearly behind
    return Math.max(0.55, Math.pow(0.88, floor));
  }
  private floorHaze(floor: number): { brightness: number; saturate: number; blur: number; tint: number } {
    // atmospheric perspective: upper floors wash out, desaturate, soften, gain cool sky tint
    const t = Math.min(1, floor / 4);
    return {
      brightness: 1 - 0.22 * t,
      saturate:   1 - 0.50 * t,
      blur:       1.2 * t,
      tint:       0.35 * t
    };
  }

  constructor(state: GameState) {
    this.state = state;
    this.root = document.createElement('div');
    this.root.className = 'market';
    this.root.innerHTML = `
      <div class="market-sky"></div>
      <div class="market-street">
        <div class="market-ground"></div>
        <div class="market-slabs"></div>
        <div class="market-stair"></div>
        <div class="market-stair market-stair-r"></div>
        <div class="market-shops"></div>
        <div class="market-people"></div>
      </div>
    `;
    document.body.appendChild(this.root);
    this.street = this.root.querySelector('.market-street') as HTMLElement;
    this.shopsRow = this.root.querySelector('.market-shops') as HTMLElement;
    this.peopleLayer = this.root.querySelector('.market-people') as HTMLElement;
    this.stairEl = this.root.querySelector('.market-stair:not(.market-stair-r)') as HTMLElement;
    this.stairElR = this.root.querySelector('.market-stair-r') as HTMLElement;
    this.slabsEl = this.root.querySelector('.market-slabs') as HTMLElement;

    this.rebuildShops();
    this.resizeHandler = () => this.onResize();
    window.addEventListener('resize', this.resizeHandler);
    this.onResize();
    this.rafId = requestAnimationFrame((t) => { this.lastT = t; this.loop(t); });
  }

  destroy(): void {
    this.alive = false;
    cancelAnimationFrame(this.rafId);
    window.removeEventListener('resize', this.resizeHandler);
    for (const c of this.customers) c.el.remove();
    this.customers.length = 0;
    for (const s of this.shops.values()) s.statsEl.remove();
    this.root.remove();
  }

  private onResize(): void {
    this.width = this.street.clientWidth;
    this.layoutShops();
  }

  private syncOpenShops(): void {
    this.openShops.length = 0;
    for (const s of this.shops.values()) {
      const ind = this.state.industries[s.defId];
      if (ind && !ind.closed) this.openShops.push(s);
    }
  }

  rebuildShops(): void {
    // remove portaled stats panels from previous build
    for (const s of this.shops.values()) s.statsEl.remove();
    this.shopsRow.innerHTML = '';
    this.shops.clear();
    // group same-category shops together; within category preserve tier order
    const categoryOrder = new Map<string, number>();
    for (let i = 0; i < INDUSTRIES.length; i++) {
      const cat = INDUSTRIES[i]!.category ?? 'Misc';
      if (!categoryOrder.has(cat)) categoryOrder.set(cat, i);
    }
    const sortedDefs = INDUSTRIES
      .map((def, idx) => ({ def, idx }))
      .sort((a, b) => {
        const ca = categoryOrder.get(a.def.category ?? 'Misc') ?? 999;
        const cb = categoryOrder.get(b.def.category ?? 'Misc') ?? 999;
        return ca !== cb ? ca - cb : a.idx - b.idx;
      })
      .map(x => x.def);
    for (const def of sortedDefs) {
      const ind = this.state.industries[def.id];
      if (!ind || !ind.unlocked) continue;
      const el = document.createElement('div');
      el.className = 'shop';
      el.style.setProperty('--shop-color', def.color);
      const count = this.state.delivered[def.id] ?? 0;
      const shortName = def.name.split(' ')[0]!.toUpperCase();
      el.innerHTML = `
        <div class="shop-badge" data-count="${count}">${icon('package', { size: 12 })} <span class="shop-badge-n">${formatNumber(count)}</span></div>
        <button class="shop-toggle" type="button" title="Open / close store">${ind.closed ? icon('lock', { size: 14 }) : icon('unlock', { size: 14 })}</button>
        <div class="shop-closed-sign">CLOSED</div>
        <div class="shop-chimney"></div>
        <div class="shop-roof"></div>
        <div class="shop-awning">
          <div class="shop-sign">${shortName}</div>
        </div>
        <div class="shop-body">
          <div class="shop-window">
            <div class="shop-display">${iconForEmoji(def.icon, { size: 28 })}</div>
            <div class="shop-glare"></div>
          </div>
          <div class="shop-door">
            <div class="shop-door-window"></div>
            <div class="shop-knob"></div>
          </div>
        </div>
        <div class="shop-step"></div>
        <div class="shop-stats">
          <div class="ss-title">${def.name}</div>
          <div class="ss-row sub"><span>Tip / unit (now)</span><span class="ss-tip">$0</span></div>
          <div class="ss-row sub"><span>Avg / sale</span><span class="ss-avg">$0</span></div>
          <div class="ss-divider"></div>
          <div class="ss-row gain"><span>+ Earned (net)</span><span class="ss-earned">$0</span></div>
          <div class="ss-row loss"><span>− Lost</span><span class="ss-lost">$0</span></div>
          <div class="ss-row loss" title="Delivery + transaction + platform fees deducted from sales"><span>− Fees</span><span class="ss-fees">$0</span></div>
          <div class="ss-row gain"><span>${icon('star', { size: 11 })} Rep gained</span><span class="ss-rep-gain">0</span></div>
          <div class="ss-row loss"><span>${icon('starOff', { size: 11 })} Rep lost</span><span class="ss-rep-loss">0</span></div>
          <div class="ss-row sub"><span>Sales / Misses</span><span class="ss-counts">0 / 0</span></div>
          <div class="ss-row sub"><span>Net</span><span class="ss-net">$0</span></div>
        </div>
      `;
      this.shopsRow.appendChild(el);
      const badgeEl = el.querySelector('.shop-badge') as HTMLElement;
      const statsEl = el.querySelector('.shop-stats') as HTMLElement;
      // portal stats out of clipped/low-z-index market so tooltip stays visible
      statsEl.remove();
      statsEl.classList.add('portal');
      document.body.appendChild(statsEl);
      if (count === 0) {
        badgeEl.classList.add('zero');
        el.classList.add('empty-shop');
      }
      if (ind.closed) el.classList.add('closed');
      const shop: Shop = { el, badgeEl, statsEl, x: 0, floor: 0, defId: def.id };
      this.shops.set(def.id, shop);
      this.renderShopStats(shop);
      const positionStats = () => {
        const r = el.getBoundingClientRect();
        statsEl.style.left = (r.left + r.width / 2) + 'px';
        statsEl.style.top = r.top + 'px';
      };
      el.addEventListener('mouseenter', () => {
        this.renderShopStats(shop);
        positionStats();
        statsEl.classList.add('visible');
      });
      el.addEventListener('mouseleave', () => statsEl.classList.remove('visible'));
      el.addEventListener('click', (e) => {
        if ((e.target as HTMLElement).closest('.shop-toggle')) return;
        this.onShopClick?.(def.id);
      });
      const toggleBtn = el.querySelector('.shop-toggle') as HTMLButtonElement | null;
      if (toggleBtn) {
        toggleBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          const nowClosed = toggleStoreClosed(this.state, def.id);
          el.classList.toggle('closed', nowClosed);
          toggleBtn.innerHTML = nowClosed ? icon('lock', { size: 14 }) : icon('unlock', { size: 14 });
          this.syncOpenShops();
        });
      }
    }
    this.syncOpenShops();
    this.rebindCustomerRefs();
    this.layoutShops();
  }

  // rebuildShops() clears this.shops, orphaning Shop refs held by in-flight customers.
  // stale target.floor would route customers up a stair that no longer exists.
  private rebindCustomerRefs(): void {
    for (let i = this.customers.length - 1; i >= 0; i--) {
      const c = this.customers[i]!;
      const newRoute: Shop[] = [];
      for (const s of c.route) {
        const nu = this.shops.get(s.defId);
        if (nu) newRoute.push(nu);
      }
      c.route = newRoute;
      if (c.routeIdx >= c.route.length) {
        c.target = null;
      } else {
        c.target = c.route[c.routeIdx] ?? null;
      }
      if (!c.target) {
        c.state = c.floor > 0 ? 'climbing-down' : 'walking-out';
        c.el.classList.remove('inside');
      }
    }
  }

  private layoutShops(): void {
    const shops = Array.from(this.shops.values());
    if (shops.length === 0 || this.width === 0) return;
    this.shopsRow.style.transform = '';
    requestAnimationFrame(() => {
      const shopW = shops[0]!.el.offsetWidth || 96;
      this.floors = Math.max(1, floorsRequired(shops.length));
      // left stair strip
      this.stairXL = SIDE_PAD;
      this.stairXR = SIDE_PAD + STAIR_W;
      // right stair strip (mirror)
      this.stairXL_R = this.width - SIDE_PAD - STAIR_W;
      this.stairXR_R = this.width - SIDE_PAD;

      const stairOffset = this.floors > 1 ? STAIR_W + SHOP_GAP : 0;
      const streetRect = this.street.getBoundingClientRect();
      for (let i = 0; i < shops.length; i++) {
        const s = shops[i]!;
        const { floor, idxInFloor } = floorIndexForShop(i);
        const cap = floorCap(floor);
        const remainingOnLast = shops.length - (i - idxInFloor);
        const rowCount = Math.min(cap, remainingOnLast);
        const fs = this.floorScale(floor);
        const effShopW = shopW * fs;
        // upper floors get strong breathing room: doubles each floor (exponential)
        const gapBoost = Math.pow(2, floor);
        const effGap = SHOP_GAP * fs * gapBoost;
        const rowTotal = rowCount * effShopW + (rowCount - 1) * effGap;
        // both sides reserve stairOffset when multi-floor
        const availForRow = this.width - SIDE_PAD * 2 - stairOffset * 2;
        const rowStartX = SIDE_PAD + stairOffset + Math.max(0, (availForRow - rowTotal) / 2);
        const cx = rowStartX + idxInFloor * (effShopW + effGap);
        s.floor = floor;
        s.el.style.left = cx + 'px';
        s.el.style.bottom = (floor * FLOOR_H) + 'px';
        // higher floor = smaller + nudged toward street center (vanishing point convergence)
        const centerX = this.width / 2;
        const convergeT = Math.min(1, floor * 0.12);
        const dxToCenter = (centerX - cx) * convergeT;
        s.el.style.transformOrigin = 'bottom left';
        s.el.style.transform = `translateX(${dxToCenter.toFixed(1)}px) scale(${fs})`;
        // atmospheric haze: brightness, desat, blur — preserve base drop-shadow from .shop
        const haze = this.floorHaze(floor);
        s.el.style.filter =
          `drop-shadow(0 4px 8px rgba(0,0,0,.5)) ` +
          `brightness(${haze.brightness.toFixed(3)}) ` +
          `saturate(${haze.saturate.toFixed(3)})` +
          (haze.blur > 0.05 ? ` blur(${haze.blur.toFixed(2)}px)` : '');
        // CSS-var driven cool tint overlay (rendered by .shop::after)
        s.el.style.setProperty('--shop-haze', haze.tint.toFixed(3));
        s.el.style.opacity = String(Math.max(0.62, 1 - floor * 0.09));
        // higher floor = further back; lower z so lower-floor shops occlude
        s.el.style.zIndex = String(50 - floor);
        const door = s.el.querySelector('.shop-door') as HTMLElement | null;
        if (door) {
          const dr = door.getBoundingClientRect();
          s.x = dr.left + dr.width / 2 - streetRect.left;
        } else {
          s.x = cx + (shopW * fs) / 2;
        }
      }

      const marketH = GROUND_H + this.floors * FLOOR_H + 20;
      this.root.style.setProperty('--market-h', marketH + 'px');
      document.body.style.setProperty('--market-h', marketH + 'px');

      // slabs: visual floor platforms beneath upper rows
      this.slabsEl.innerHTML = '';
      const slabH = 12;
      for (let f = 1; f < this.floors; f++) {
        const slab = document.createElement('div');
        slab.className = 'market-floor-slab';
        slab.style.left = SIDE_PAD + 'px';
        slab.style.right = SIDE_PAD + 'px';
        slab.style.bottom = (GROUND_H + f * FLOOR_H - slabH) + 'px';
        slab.style.height = slabH + 'px';
        this.slabsEl.appendChild(slab);
      }

      // stair: zigzag diagonal SVG, both sides
      if (this.floors > 1) {
        const stripH = this.floors * FLOOR_H;
        const stripWL = this.stairXR - this.stairXL;
        this.stairEl.style.display = 'block';
        this.stairEl.style.left = this.stairXL + 'px';
        this.stairEl.style.width = stripWL + 'px';
        this.stairEl.style.bottom = GROUND_H + 'px';
        this.stairEl.style.height = stripH + 'px';
        this.stairEl.innerHTML = this.renderStairSVG(stripWL, stripH, 'L');
        const stripWR = this.stairXR_R - this.stairXL_R;
        this.stairElR.style.display = 'block';
        this.stairElR.style.left = this.stairXL_R + 'px';
        this.stairElR.style.width = stripWR + 'px';
        this.stairElR.style.bottom = GROUND_H + 'px';
        this.stairElR.style.height = stripH + 'px';
        this.stairElR.innerHTML = this.renderStairSVG(stripWR, stripH, 'R');
      } else {
        this.stairEl.style.display = 'none';
        this.stairEl.innerHTML = '';
        this.stairElR.style.display = 'none';
        this.stairElR.innerHTML = '';
      }
    });
  }

  private renderStairSVG(stripW: number, stripH: number, side: 'L' | 'R' = 'L'): string {
    const flights = this.floors - 1;
    let paths = '';
    // side L: inner = right edge (stripW); side R: inner = left edge (0)
    const innerX = side === 'L' ? stripW : 0;
    const outerX = side === 'L' ? 0 : stripW;
    for (let i = 0; i < flights; i++) {
      // flight i: floor i (bottom) → floor i+1 (top)
      const yBottom = stripH - i * FLOOR_H;
      const yTop = stripH - (i + 1) * FLOOR_H;
      const xBottom = i % 2 === 0 ? innerX : outerX;
      const xTop = i % 2 === 0 ? outerX : innerX;
      // perpendicular step ticks along flight
      const stepCount = 12;
      let steps = '';
      const dx = xTop - xBottom;
      const dy = yTop - yBottom;
      const len = Math.hypot(dx, dy);
      const nx = -dy / len;  // perpendicular
      const ny =  dx / len;
      const stepLen = 7;
      for (let s = 1; s < stepCount; s++) {
        const t = s / stepCount;
        const px = xBottom + dx * t;
        const py = yBottom + dy * t;
        const x1 = px - nx * stepLen;
        const y1 = py - ny * stepLen;
        const x2 = px + nx * stepLen;
        const y2 = py + ny * stepLen;
        steps += `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="#5a3a26" stroke-width="2" stroke-linecap="round"/>`;
      }
      // rails: parallel lines offset perpendicular
      const railOff = 9;
      const rail = (sign: number) => `M ${(xBottom + nx * sign * railOff).toFixed(1)} ${(yBottom + ny * sign * railOff).toFixed(1)} L ${(xTop + nx * sign * railOff).toFixed(1)} ${(yTop + ny * sign * railOff).toFixed(1)}`;
      paths += `
        <g class="stair-flight">
          <path d="${rail(-1)}" stroke="#2a1d14" stroke-width="3" stroke-linecap="round" fill="none"/>
          <path d="${rail(1)}"  stroke="#2a1d14" stroke-width="3" stroke-linecap="round" fill="none"/>
          ${steps}
          <line x1="${xBottom}" y1="${yBottom}" x2="${xTop}" y2="${yTop}" stroke="#4a3324" stroke-width="3" stroke-linecap="round" opacity=".55"/>
        </g>
      `;
      // landing pad at top of flight (small platform on floor i+1)
      const padW = 18;
      const padX = xTop;
      const padY = yTop;
      paths += `<rect x="${(padX - padW / 2).toFixed(1)}" y="${(padY - 4).toFixed(1)}" width="${padW}" height="6" fill="#3a2820" stroke="#1a1108" stroke-width="1" rx="1"/>`;
    }
    return `<svg viewBox="0 0 ${stripW} ${stripH}" width="${stripW}" height="${stripH}" preserveAspectRatio="none" style="overflow:visible">${paths}</svg>`;
  }

  private advanceRoute(c: Customer): boolean {
    c.routeIdx++;
    while (c.routeIdx < c.route.length) {
      const next = c.route[c.routeIdx]!;
      const ind = this.state.industries[next.defId];
      if (ind && !ind.closed) {
        c.target = next;
        return true;
      }
      c.routeIdx++;
    }
    c.target = null;
    return false;
  }

  private spawnCustomer(): void {
    const shops = this.openShops;
    if (shops.length === 0) return;
    const fromLeft = Math.random() < 0.5;
    const fx = customerEffects(this.state);
    const wealth = rollWealth(this.state.reputation, fx.wealthyBonus, fx.whaleBonus);
    // multi-shop route; tier sets max stops, actual length random within cap
    const maxStops = wealth.tier === 'whale'   ? 5
                   : wealth.tier === 'wealthy' ? 3
                   : wealth.tier === 'broke'   ? 1
                   :                             2;
    const desired = 1 + Math.floor(Math.random() * maxStops);
    const stops = Math.min(desired, shops.length);
    // weighted draw without replacement: each tier picks shops matching its demand curve.
    // weights recomputed against the highest-tier open shop so the curve scales as new
    // industries unlock — early game broke pool still favors lemonade, late game it dilutes.
    let maxTierIdx = 0;
    for (const s of shops) {
      const ti = TIER_INDEX.get(s.defId) ?? 0;
      if (ti > maxTierIdx) maxTierIdx = ti;
    }
    const pool = shops.slice();
    const route: Shop[] = [];
    for (let i = 0; i < stops; i++) {
      const weights = pool.map(s => demandWeight(wealth.tier, TIER_INDEX.get(s.defId) ?? 0, maxTierIdx));
      const idx = weightedPick(pool, weights);
      route.push(pool.splice(idx, 1)[0]!);
    }
    const target = route[0]!;

    const el = document.createElement('div');
    el.className = 'customer';
    const body = document.createElement('span');
    body.className = 'c-body';
    body.innerHTML = svgPerson();
    const product = document.createElement('span');
    product.className = 'c-product';
    el.appendChild(body);
    el.appendChild(product);

    el.classList.add('wealth-' + wealth.tier);
    if (wealth.icon) {
      const badge = document.createElement('span');
      badge.className = 'c-wealth';
      badge.innerHTML = icon(wealth.icon, { size: 12 });
      if (wealth.units > 1) {
        const qty = document.createElement('span');
        qty.className = 'c-wealth-qty';
        qty.textContent = '×' + wealth.units;
        badge.appendChild(qty);
      }
      el.appendChild(badge);
    }
    if (route.length > 1) {
      const tripBadge = document.createElement('span');
      tripBadge.className = 'c-trip';
      tripBadge.textContent = route.length + '🛒';
      el.appendChild(tripBadge);
    }

    this.peopleLayer.appendChild(el);
    const startX = fromLeft ? -30 : this.width + 30;
    const side: 'L' | 'R' = fromLeft ? 'L' : 'R';
    const speedBase = wealth.tier === 'whale' ? 30 : wealth.tier === 'wealthy' ? 40 : 50;
    const speed = (speedBase + Math.random() * 40) * fx.walkSpeed;
    // initial horizontal direction: toward stair if target on upper floor, else direct to shop
    const initialAim = target.floor > 0 ? this.stairBottomX(0, side) : target.x;
    const vx = initialAim > startX ? speed : -speed;
    const facing: 1 | -1 = vx >= 0 ? 1 : -1;
    const lane = Math.random();
    const baseScale = 1 - lane * 0.18;
    el.style.transform = `translate3d(${startX}px, 0, 0) scale(${baseScale})`;
    body.style.transform = `scaleX(${facing})`;
    this.customers.push({
      el, body, product,
      x: startX, y: 0, vx, target,
      route, routeIdx: 0,
      state: 'walking-in',
      shopTimer: 0,
      facing,
      wealth,
      floor: 0,
      lane,
      baseScale,
      side
    });
  }

  flyProduct(defId: string, cycles: number = 1): void {
    const ind = this.state.industries[defId];
    if (!ind) return;
    const totalProducts = ind.count * cycles;
    if (totalProducts <= 0) return;

    // stock is added immediately so customers can buy even mid-flight (no starvation
    // when production cycle is faster than parcel animation)
    this.state.delivered[defId] = (this.state.delivered[defId] ?? 0) + totalProducts;
    this.updateBadge(defId, totalProducts);

    // coalesce pending qty per shop; only one batch animates at a time
    const q = this.parcelQueue.get(defId) ?? { pending: 0, active: false };
    q.pending += totalProducts;
    this.parcelQueue.set(defId, q);
    this.tryFlushParcels(defId);
  }

  private tryFlushParcels(defId: string): void {
    const q = this.parcelQueue.get(defId);
    if (!q || q.pending <= 0 || q.active) return;
    const qty = q.pending;
    q.pending = 0;
    q.active = true;
    this.launchParcels(defId, qty);
  }

  private launchParcels(defId: string, totalProducts: number): void {
    const shop = this.shops.get(defId);
    const def = INDUSTRIES_BY_ID.get(defId);
    const card = document.querySelector(`[data-card="${defId}"]`) as HTMLElement | null;
    if (!shop || !def || !card) {
      const q = this.parcelQueue.get(defId);
      if (q) { q.active = false; this.tryFlushParcels(defId); }
      return;
    }

    const cardRect = card.getBoundingClientRect();
    const chimney = shop.el.querySelector('.shop-chimney') as HTMLElement | null;
    const landRect = (chimney ?? shop.el).getBoundingClientRect();

    const startX = cardRect.left + cardRect.width / 2;
    const startY = cardRect.top + cardRect.height / 2;
    const endX = landRect.left + landRect.width / 2;
    const endY = chimney ? landRect.top - 2 : landRect.bottom - 16;
    const dx = endX - startX;
    const dy = endY - startY;
    const apex = Math.max(180, Math.abs(dx) * 0.32);

    // batch into fewer, bigger parcels — keeps screen calm at high throughput
    const n = totalProducts <= 3 ? totalProducts
            : totalProducts <= 30 ? 2
            : 3;
    const base = Math.floor(totalProducts / n);
    const extra = totalProducts - base * n;

    // small parcel; gentle growth with chunk
    const sizeFor = (chunk: number): number =>
      Math.min(1.5, 0.75 + Math.log10(Math.max(1, chunk)) * 0.22);

    const dur = 700 + Math.min(220, Math.abs(dx) * 0.18);
    const stagger = 130;
    let lastFinishAt = 0;

    for (let i = 0; i < n; i++) {
      const chunk = base + (i < extra ? 1 : 0);
      const scaleFactor = sizeFor(chunk);

      const fly = document.createElement('div');
      fly.className = 'parcel';
      fly.style.setProperty('--parcel-scale', scaleFactor.toFixed(2));
      const parcelIcon = document.createElement('span');
      parcelIcon.className = 'parcel-icon';
      parcelIcon.innerHTML = iconForEmoji(def.icon, { size: 18 });
      const tape = document.createElement('span');
      tape.className = 'parcel-tape';
      fly.appendChild(tape);
      fly.appendChild(parcelIcon);
      if (chunk > 1) {
        const qty = document.createElement('span');
        qty.className = 'parcel-qty';
        qty.textContent = '×' + formatNumber(chunk);
        fly.appendChild(qty);
      }
      fly.style.left = startX + 'px';
      fly.style.top = startY + 'px';
      document.body.appendChild(fly);

      const steps = 24;
      const frames: Keyframe[] = [];
      for (let s = 0; s <= steps; s++) {
        const t = s / steps;
        const tx = 1 - Math.pow(1 - t, 2);
        const x = dx * tx;
        const y = dy * t - apex * 4 * t * (1 - t);
        const wobble = Math.sin(t * Math.PI * 3) * 10 * (1 - t);
        const launchScale = s === 0 ? scaleFactor * 0.6 : scaleFactor;
        const opacity = s === 0 ? 0 : 1;
        frames.push({
          transform: `translate(calc(-50% + ${x}px), calc(-50% + ${y}px)) rotate(${wobble}deg) scale(${launchScale})`,
          opacity
        });
      }
      const anim = fly.animate(frames, {
        duration: dur,
        delay: i * stagger,
        easing: 'linear',
        fill: 'forwards'
      });
      const finishAt = dur + i * stagger;
      if (finishAt > lastFinishAt) lastFinishAt = finishAt;

      const isLast = i === n - 1;
      let settled = false;
      const settle = (): void => {
        if (settled) return;
        settled = true;
        if (isLast) {
          const q = this.parcelQueue.get(defId);
          if (q) { q.active = false; this.tryFlushParcels(defId); }
        }
      };
      anim.addEventListener('finish', () => {
        this.chimneyPuff(endX, endY, scaleFactor);
        this.glowWindow(shop.el);
        anim.cancel();
        fly.classList.add('parcel-land');
        setTimeout(() => fly.remove(), 320);
        settle();
      }, { once: true });
      setTimeout(() => { anim.cancel(); fly.remove(); settle(); }, dur + i * stagger + 1500);
    }
  }

  private chimneyPuff(x: number, y: number, scale: number = 1): void {
    const count = scale > 1.3 ? 4 : 3;
    for (let i = 0; i < count; i++) {
      const puff = document.createElement('div');
      puff.className = 'smoke-puff';
      const jitterX = (Math.random() - 0.5) * 8;
      puff.style.left = (x + jitterX) + 'px';
      puff.style.top = y + 'px';
      puff.style.animationDelay = (i * 70) + 'ms';
      puff.style.setProperty('--puff-scale', scale.toFixed(2));
      document.body.appendChild(puff);
      setTimeout(() => puff.remove(), 1500);
    }
  }

  private glowWindow(shopEl: HTMLElement): void {
    const win = shopEl.querySelector('.shop-window') as HTMLElement | null;
    if (!win) return;
    win.classList.remove('stock-glow');
    requestAnimationFrame(() => win.classList.add('stock-glow'));
    setTimeout(() => win.classList.remove('stock-glow'), 650);
  }

  private salesMilestoneToast(shop: Shop, indName: string, label: string, mult: number): void {
    const def = INDUSTRIES_BY_ID.get(shop.defId);
    notify(`${icon('trophy', { size: 12 })} ${indName}: ${label} · ×${mult} sales revenue`, { color: categoryColor(def?.category) });
  }

  private flyReputation(shop: Shop, text: string, kind: 'gain' | 'loss'): void {
    const chimney = shop.el.querySelector('.shop-chimney') as HTMLElement | null;
    const repBar = document.getElementById('rep');
    if (!repBar) return;
    const srcRect = (chimney ?? shop.el).getBoundingClientRect();
    const dstRect = repBar.getBoundingClientRect();
    const startX = srcRect.left + srcRect.width / 2;
    const startY = srcRect.top;
    const endX = dstRect.left + dstRect.width / 2;
    const endY = dstRect.top + dstRect.height / 2;
    const dx = endX - startX;
    const dy = endY - startY;
    const arcLift = -Math.min(220, Math.abs(dx) * 0.3 + 80);
    const spin = kind === 'gain' ? 360 : -25;

    const fly = document.createElement('div');
    fly.className = 'flying-rep ' + kind;
    fly.innerHTML = (kind === 'gain' ? icon('star', { size: 12 }) : icon('starOff', { size: 12 })) + ' ' + text;
    fly.style.left = startX + 'px';
    fly.style.top = startY + 'px';
    document.body.appendChild(fly);

    const steps = 36;
    const frames: Keyframe[] = [];
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const te = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
      const x = dx * te;
      const y = dy * te + arcLift * 4 * te * (1 - te);
      const rot = spin * te;
      let scale: number;
      if (t < 0.12) scale = 0.4 + (1.1 - 0.4) * (t / 0.12);
      else if (t > 0.88) scale = 1.1 + (1.35 - 1.1) * ((t - 0.88) / 0.12);
      else scale = 1.0 + 0.12 * Math.sin(((t - 0.12) / 0.76) * Math.PI);
      let opacity: number;
      if (t < 0.08) opacity = t / 0.08;
      else if (t > 0.94) opacity = 1 - (t - 0.94) / 0.06;
      else opacity = 1;
      frames.push({
        transform: `translate(calc(-50% + ${x}px), calc(-50% + ${y}px)) scale(${scale}) rotate(${rot}deg)`,
        opacity
      });
    }
    const anim = fly.animate(frames, {
      duration: 1100,
      easing: 'linear',
      fill: 'forwards'
    });
    const onArrive = () => {
      fly.remove();
      this.pulseRepBar(kind);
    };
    anim.addEventListener('finish', onArrive, { once: true });
    setTimeout(() => fly.remove(), 2200);
  }

  private pulseRepBar(kind: 'gain' | 'loss'): void {
    const bar = document.getElementById('rep');
    if (!bar) return;
    const cls = kind === 'gain' ? 'rep-pulse-gain' : 'rep-pulse-loss';
    bar.classList.remove(cls);
    requestAnimationFrame(() => bar.classList.add(cls));
    setTimeout(() => bar.classList.remove(cls), 750);
  }

  private getStats(defId: string): ShopStats {
    let s = this.state.shopStats[defId];
    if (!s) {
      s = emptyShopStats();
      this.state.shopStats[defId] = s;
    }
    return s;
  }

  private renderShopStats(shop: Shop): void {
    const s = this.getStats(shop.defId);
    const def = INDUSTRIES_BY_ID.get(shop.defId);
    const fmtM = (n: number) => formatMoney(n);
    const setText = (sel: string, txt: string) => {
      const el = shop.statsEl.querySelector(sel);
      if (el) el.textContent = txt;
    };
    const tip = def ? perUnitRevenue(def, this.state) * TIP_FRACTION : 0;
    setText('.ss-tip', fmtM(tip));
    const avg = s.sales > 0 ? s.extraEarned / s.sales : 0;
    setText('.ss-avg', s.sales > 0 ? fmtM(avg) : '—');
    setText('.ss-earned', '+' + fmtM(s.extraEarned));
    setText('.ss-lost', '-' + fmtM(s.extraLost));
    setText('.ss-fees', '-' + fmtM(s.feesPaid));
    setText('.ss-rep-gain', '+' + formatNumber(s.repGained));
    setText('.ss-rep-loss', '-' + formatNumber(s.repLost));
    setText('.ss-counts', formatNumber(s.sales) + ' / ' + formatNumber(s.misses));
    const net = s.extraEarned - s.extraLost;
    setText('.ss-net', (net >= 0 ? '+' : '-') + fmtM(Math.abs(net)));
    const netEl = shop.statsEl.querySelector('.ss-net') as HTMLElement | null;
    if (netEl) {
      netEl.classList.toggle('pos', net > 0);
      netEl.classList.toggle('neg', net < 0);
    }
  }

  private floatMoney(parent: HTMLElement, text: string, kind: 'gain' | 'loss'): void {
    const float = document.createElement('div');
    float.className = 'badge-float money-float ' + kind;
    float.textContent = text;
    parent.appendChild(float);
    setTimeout(() => float.remove(), 1000);
  }

  private updateBadge(defId: string, delta: number = 0): void {
    const shop = this.shops.get(defId);
    if (!shop) return;
    const count = this.state.delivered[defId] ?? 0;
    const numEl = shop.badgeEl.querySelector('.shop-badge-n');
    if (numEl) numEl.textContent = formatNumber(count);
    shop.badgeEl.classList.toggle('zero', count === 0);
    shop.el.classList.toggle('empty-shop', count === 0);
    // restart pulse anim via Web Animations API — no forced reflow
    shop.badgeEl.classList.remove('pulse');
    requestAnimationFrame(() => shop.badgeEl.classList.add('pulse'));

    if (delta > 0) {
      const float = document.createElement('div');
      float.className = 'badge-float';
      float.textContent = '+' + formatNumber(delta);
      shop.el.appendChild(float);
      setTimeout(() => float.remove(), 900);
    }
  }

  private loop(now: number): void {
    const dt = Math.min(0.1, (now - this.lastT) / 1000);
    this.lastT = now;

    // sync shops with unlock state
    let needRebuild = false;
    for (const def of INDUSTRIES) {
      const ind = this.state.industries[def.id];
      const has = this.shops.has(def.id);
      if (ind && ind.unlocked && !has) needRebuild = true;
    }
    if (needRebuild) this.rebuildShops();

    const fx = customerEffects(this.state);
    // spawn rate scales with unlocked count + reputation + upgrades
    const unlocked = this.shops.size;
    const base = unlocked === 0 ? 0 : Math.min(3, 0.4 + unlocked * 0.25);
    const spawnPerSec = base * reputationSpawnMultiplier(this.state.reputation) * fx.spawnRate;
    this.spawnAcc += dt * spawnPerSec;
    while (this.spawnAcc >= 1 && this.customers.length < 40) {
      this.spawnAcc -= 1;
      this.spawnCustomer();
    }

    for (let i = this.customers.length - 1; i >= 0; i--) {
      const c = this.customers[i]!;
      // rescue: relayout may have removed floors customer was standing/climbing on
      if (c.floor >= this.floors) {
        c.floor = 0;
        c.y = 0;
        c.state = 'walking-out';
        c.target = null;
        c.el.classList.remove('inside');
        const dir = c.x < this.width / 2 ? -1 : 1;
        c.vx = dir * 60;
        c.facing = dir as 1 | -1;
      } else if ((c.state === 'climbing-up' || c.state === 'climbing-down') && c.floor + 1 >= this.floors && c.state === 'climbing-up') {
        // mid-climb to floor that no longer exists
        c.y = c.floor * FLOOR_H;
        c.state = 'walking-out';
        c.target = null;
      }
      if (c.state === 'walking-in' && c.target) {
        const targetInd = this.state.industries[c.target.defId];
        if (targetInd && targetInd.closed) {
          // store closed mid-trip — try next shop in route, else leave
          if (!this.advanceRoute(c)) {
            c.state = 'walking-out';
            const exitRight = c.vx >= 0;
            const exitSpeed = 40 + Math.random() * 30;
            c.vx = (exitRight ? 1 : -1) * exitSpeed;
            c.facing = c.vx >= 0 ? 1 : -1;
          }
        } else {
          // same floor: head to door. below target: walk to stair bottom (up). above target: walk to stair top (down).
          let aimX: number;
          if (c.floor === c.target.floor) {
            aimX = c.target.x;
          } else if (c.floor < c.target.floor) {
            aimX = this.stairBottomX(c.floor, c.side);
          } else {
            aimX = this.stairTopX(c.floor - 1, c.side);
          }
          const speed = Math.abs(c.vx) || 50;
          c.vx = (aimX > c.x ? 1 : -1) * speed;
          c.facing = c.vx >= 0 ? 1 : -1;
          c.x += c.vx * dt;
          const reached = (c.vx > 0 && c.x >= aimX) || (c.vx < 0 && c.x <= aimX);
          if (reached) {
            c.x = aimX;
            if (c.floor === c.target.floor) {
              c.state = 'shopping';
              c.shopTimer = (0.6 + Math.random() * 1.2) * fx.shopDwell;
              c.el.classList.add('inside');
            } else if (c.floor < c.target.floor) {
              c.state = 'climbing-up';
            } else {
              c.state = 'climbing-down';
            }
          }
        }
      } else if (c.state === 'climbing-up' && c.target) {
        // safety: target moved to current/lower floor mid-climb — abort climb
        if (c.target.floor <= c.floor) {
          c.y = c.floor * FLOOR_H;
          c.state = 'walking-in';
        } else {
          c.y += CLIMB_SPEED * dt;
          const flight = c.floor;
          const nextFloorY = (flight + 1) * FLOOR_H;
          c.x = this.climbX(flight, c.y, c.side);
          c.facing = this.stairTopX(flight, c.side) >= this.stairBottomX(flight, c.side) ? 1 : -1;
          if (c.y >= nextFloorY) {
            c.y = nextFloorY;
            c.floor += 1;
            c.x = this.stairTopX(flight, c.side);
            c.state = 'walking-in';
          }
        }
      } else if (c.state === 'climbing-down') {
        c.y -= CLIMB_SPEED * dt;
        const flight = Math.max(0, c.floor - 1);
        const prevFloorY = Math.max(0, flight * FLOOR_H);
        c.x = this.climbX(flight, c.y, c.side);
        c.facing = this.stairBottomX(flight, c.side) >= this.stairTopX(flight, c.side) ? 1 : -1;
        if (c.y <= prevFloorY) {
          c.y = prevFloorY;
          c.floor = flight;
          c.x = this.stairBottomX(flight, c.side);
          // mid-trip descent: resume walking-in if more route or current floor has target
          if (c.target && c.target.floor >= c.floor) {
            c.state = 'walking-in';
          } else if (c.floor <= 0) {
            c.floor = 0;
            c.state = 'walking-out';
            const exitRight = Math.random() < 0.5;
            const exitSpeed = 50 + Math.random() * 40;
            c.vx = (exitRight ? 1 : -1) * exitSpeed;
            c.facing = c.vx >= 0 ? 1 : -1;
          }
        }
      } else if (c.state === 'shopping') {
        c.shopTimer -= dt;
        if (c.shopTimer <= 0) {
          c.el.classList.remove('inside');
          const defId = c.target!.defId;
          const stock = this.state.delivered[defId] ?? 0;
          let exitSpeed: number;
          const stats = this.getStats(defId);
          if (stock > 0) {
            // sale: serve as many units as customer wants (capped by stock)
            const wanted = c.wealth.units;
            const sold = Math.min(stock, wanted);
            this.state.delivered[defId] = stock - sold;
            const def = INDUSTRIES_BY_ID.get(defId);
            if (def) {
              c.product.innerHTML = iconForEmoji(def.icon, { size: 14 });
              const whaleBoost = c.wealth.tier === 'whale' ? fx.whaleTip : 1;
              const grossTip = perUnitRevenue(def, this.state) * TIP_FRACTION * c.wealth.multiplier * sold * fx.tipMult * whaleBoost;
              const fees = computeSaleFees(def, grossTip, sold);
              const feeCapped = Math.min(fees.total, grossTip);
              const netTip = grossTip - feeCapped;
              this.state.money += netTip;
              this.state.totalEarned += netTip;
              stats.extraEarned += netTip;
              stats.feesPaid += feeCapped;
              const targetEl = c.target!.el;
              this.floatMoney(targetEl, '+' + formatMoney(netTip), 'gain');
              if (feeCapped > 0) {
                setTimeout(() => this.floatMoney(targetEl, '−' + formatMoney(feeCapped) + ' fees', 'loss'), 220);
              }
            }
            // rep gain scales with wealth tier (whales love it more)
            const repGain = Math.round(
              REPUTATION_GAIN
                * (c.wealth.tier === 'whale' ? 3 : c.wealth.tier === 'wealthy' ? 2 : 1)
                * fx.repGainMult
            );
            this.state.reputation = clampReputation(this.state.reputation + repGain);
            stats.repGained += repGain;
            this.flyReputation(c.target!, '+' + repGain, 'gain');
            // partial-fill annoys whales: small rep ding if didn't get full order (unless forgiven)
            if (sold < wanted && !fx.partialForgive) {
              const partial = Math.max(1, Math.floor((REPUTATION_LOSS / 2) * fx.repLossMult));
              this.state.reputation = clampReputation(this.state.reputation - partial);
              stats.repLost += partial;
            }
            stats.sales += 1;
            const prevSold = stats.unitsSold;
            stats.unitsSold += sold;
            // toast on crossing a sales milestone
            for (const ms of SALES_MILESTONES) {
              if (prevSold < ms.units && stats.unitsSold >= ms.units) {
                const defForToast = INDUSTRIES_BY_ID.get(defId);
                if (defForToast) {
                  this.salesMilestoneToast(c.target!, defForToast.name, ms.label, ms.mult);
                }
                break;
              }
            }
            c.el.classList.add('carrying');
            this.updateBadge(defId);
            this.renderShopStats(c.target!);
            exitSpeed = 50 + Math.random() * 40;
          } else {
            // empty store: customer leaves dejected — wealthy customers hurt more
            const def = INDUSTRIES_BY_ID.get(defId);
            if (def) {
              const raw = perUnitBase(def, this.state)
                * reputationPenaltyMultiplier(this.state.reputation)
                * c.wealth.multiplier
                * fx.repLossMult;
              const penalty = Math.min(this.state.money, raw);
              this.state.money -= penalty;
              stats.extraLost += penalty;
              this.floatMoney(c.target!.el, '-' + formatMoney(penalty), 'loss');
            }
            const repLoss = Math.max(1, Math.round(
              REPUTATION_LOSS
                * (c.wealth.tier === 'whale' ? 4 : c.wealth.tier === 'wealthy' ? 2 : 1)
                * fx.repLossMult
            ));
            this.state.reputation = clampReputation(this.state.reputation - repLoss);
            stats.repLost += repLoss;
            stats.misses += 1;
            this.flyReputation(c.target!, '-' + repLoss, 'loss');
            this.renderShopStats(c.target!);
            c.el.classList.add('empty');
            // flag shop as sold-out for a moment
            c.target!.el.classList.add('sold-out');
            setTimeout(() => c.target?.el.classList.remove('sold-out'), 1500);
            exitSpeed = 25 + Math.random() * 15; // slower, dejected shuffle
          }
          // advance to next shop in route; else exit
          if (this.advanceRoute(c)) {
            c.state = 'walking-in';
            // aim toward next shop's column (or stair if cross-floor)
            const aimX = (c.floor === c.target!.floor)
              ? c.target!.x
              : this.stairBottomX(c.floor, c.side);
            c.vx = (aimX > c.x ? 1 : -1) * exitSpeed;
            c.facing = c.vx >= 0 ? 1 : -1;
          } else {
            c.state = 'walking-out';
            if (c.floor > 0) {
              const aim = this.stairTopX(c.floor - 1, c.side);
              c.vx = (aim > c.x ? 1 : -1) * exitSpeed;
            } else {
              const exitRight = Math.random() < 0.5;
              c.vx = (exitRight ? 1 : -1) * exitSpeed;
            }
            c.facing = c.vx >= 0 ? 1 : -1;
          }
        }
      } else if (c.state === 'walking-out') {
        if (c.floor > 0) {
          // walk to top of descending stair, then climb down
          const aim = this.stairTopX(c.floor - 1, c.side);
          c.vx = (aim > c.x ? 1 : -1) * (Math.abs(c.vx) || 50);
          c.facing = c.vx >= 0 ? 1 : -1;
          c.x += c.vx * dt;
          if ((c.vx > 0 && c.x >= aim) || (c.vx < 0 && c.x <= aim)) {
            c.x = aim;
            c.state = 'climbing-down';
          }
        } else {
          c.x += c.vx * dt;
          if (c.x < -50 || c.x > this.width + 50) {
            c.el.remove();
            this.customers.splice(i, 1);
            continue;
          }
        }
      }
      const laneLift = c.lane * 10;
      // depth scale tracks vertical position; climbers shrink smoothly between floors
      const effFloor = Math.max(c.floor, c.y / FLOOR_H);
      const depthScale = this.floorScale(effFloor);
      c.el.style.transform = `translate3d(${c.x}px, ${-(c.y + laneLift)}px, 0) scale(${c.baseScale * depthScale})`;
      c.el.style.zIndex = String(1000 + c.floor * 200 - Math.round(c.lane * 100));
      c.body.style.transform = `scaleX(${c.facing})`;
      c.el.classList.toggle('climbing', c.state === 'climbing-up' || c.state === 'climbing-down');
    }

    if (this.alive) this.rafId = requestAnimationFrame((t) => this.loop(t));
  }
}
